38	// Resolve user/agent-provided deps: normalize paths, drop nonexistent files and build output,
39	// downgrade unknown symbols to file-level deps. Returns {deps, dropped}.
40	export function resolveDeps(repo, deps) {
41	  const out = [], dropped = [];
42	  const seen = new Set();
43	  for (const d of deps || []) {
44	    const p = normPath(repo, d.path);
45	    const abs = p && repoFile(repo, p);
46	    if (!abs || !fs.existsSync(abs) || fs.statSync(abs).isDirectory()) { dropped.push({ ...d, reason: 'outside repository, symlinked outside, or no such file' }); continue; }
47	    if (TRANSIENT.test(p)) { dropped.push({ ...d, reason: 'build or run output; point at the code that produces it' }); continue; }
48	    const key = p + '|' + (d.symbol || '');
49	    if (seen.has(key)) continue;
50	    seen.add(key);
51	    const h = hashDep(repo, { path: p, symbol: d.symbol || undefined });
52	    if (h.symbolMissing) { dropped.push({ ...d, reason: 'symbol not found; kept file-level dep' }); delete h.symbol; delete h.symbolMissing; }
53	    out.push(h);
54	  }
55	  return { deps: out, dropped };
56	}
