58	// Pull `path/to/file.py:Symbol` (and bare `Class.method` / `func()` that exist in
59	// an already-listed file) pointers out of a note body so every claim is tracked.
60	export function extractDeps(repo, body, listed = []) {
61	  const out = [];
62	  const seen = new Set(listed.map(d => `${normPath(repo, d.path)}|${d.symbol || ''}`));
63	  const files = [...new Set(listed.map(d => normPath(repo, d.path)))];
