69	    if (!files.includes(p)) files.push(p);
70	    add(p, m[2] && !/^\d/.test(m[2]) ? m[2].replace(/\.$/, '') : undefined);
71	  }
72	  // bare Class.method / module.func / func() mentions: attach to the file that defines them
73	  const bare = /(?<![\w/.])([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+|[A-Za-z_]\w*(?=\(\)))/g;
74	  while ((m = bare.exec(body))) {
75	    const sym = m[1];
76	    if (sym.length < 4 || /^(e\.g|i\.e|etc|vs)\b/i.test(sym) || /^\d/.test(sym)) continue;
77	    const parts = sym.split('.');
78	    if (parts.length >= 2 && /^(self|cls|this|ctx|state|args|kwargs|opts|params|value|obj|super|module|exports|process|window|document|console|std|t|os|sys|re|json|fs|path)$/.test(parts[0])) continue;
79	    let done = false;
80	    if (parts.length >= 2 && /^[a-z_]\w*$/.test(parts[0])) {
81	      // module.func: resolve module to a file
82	      for (const ext of ['py', 'js', 'ts', 'tsx', 'go', 'rb', 'rs']) {
83	        const f = findFile(repo, parts[0] + '.' + ext, files);
84	        if (f) { const h = hashDep(repo, { path: f, symbol: parts.slice(1).join('.') }); if (!h.missing && !h.symbolMissing) { if (!files.includes(f)) files.push(f); add(f, parts.slice(1).join('.')); } done = true; break; }
85	      }
86	      done = true; // lowercase receiver that is not a module: never guess
87	    }
88	    if (done) continue;
