97	function findFile(repo, p, files) {
98	  // resolve a short path like `core.py` against the directories of listed files, then the repo
99	  const base = path.basename(p);
100	  for (const f of files) { const cand = path.join(path.dirname(f), p); if (fs.existsSync(path.join(repo, cand))) return cand; }
101	  for (const f of files) { const cand = path.join(path.dirname(f), base); if (fs.existsSync(path.join(repo, cand))) return cand; }
102	  try {
103	    const hits = execFileSync('git', ['ls-files', '--', `*${p}`], { cwd: repo, stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim().split('\n').filter(Boolean);
