149	// verification batch (maintain.js:pickStale), and a one-time reset puts it straight back (stale-reset.js
150	// re-hashes a gone file to `missing` again). Thinker refuses such a note at creation already
151	// (`createNote`: an anchor must be an existing file); this applies the same rule to one whose files went
152	// away afterwards, with no model call. Nothing that was being served stops being served: these notes
153	// were already withheld. A desired behavior and a skill card are a person's own, and so is a note someone
154	// wrote by hand - those are left for a person to decide on. Returns the gone paths, or null.
155	export function anchorsGone(note, changed) {
156	  if (['behavior', 'skill'].includes(note.kind) || note.source?.type === 'human') return null;
157	  const paths = [...new Set((note.deps || []).map(d => d.path).filter(p => p && !TRANSIENT.test(p)))];
