163	// Code edits queue verification without withholding the note. Missing anchors and explicit
164	// contradictions still withhold it. Old hash-only stale records migrate here without rebaselining.
165	export function refresh(store, notes = store.list(), { persist = true, narrow = false } = {}) {
166	  return notes.map(n => {
167	    if (n.status === 'invalid') return n;
168	    // a broken skill (skills.js) stays as it is until its file changes or a person reviews it: a code
169	    // change alone does not put it back into audit
170	    if (n.status === 'broken') return n;
171	    const { changed, deps, upgraded } = checkNote(store.repo, n, { narrow });
172	    const wasWaiting = needsVerification(n);
173	    if (changed.length) {
174	      // every file the note rests on is gone: retired here rather than left stale for good (above)
175	      const gone = anchorsGone(n, changed);
176	      if (gone) {
177	        const next = { ...n, status: 'invalid', invalidReason: `anchors removed: ${gone.slice(0, 3).join(', ')}` };
178	        delete next.stale;
179	        delete next.recheck;
180	        if (persist) { store.put(next); store.log({ op: 'retire-gone', id: next.id, kind: next.kind, paths: gone.slice(0, 10) }); }
181	        return next;
182	      }
183	      const status = n.contradicted || missingAnchor(changed) ? 'stale' : 'pending';
184	      const field = status === 'stale' ? 'stale' : 'recheck';
185	      const waiting = { since: n.recheck?.since || n.stale?.since || new Date().toISOString(), changed };
186	      // a whole-file dep narrowed to definitions (checkNote with narrow) is kept although the note
187	      // awaits verification: the changed definitions carry their hash from the verified commit, so they
188	      // still read as changed, and the verification sees symbols rather than the file
189	      const next = { ...n, status, [field]: waiting, ...(upgraded ? { deps } : {}) };
190	      delete next[field === 'stale' ? 'recheck' : 'stale'];
191	      if (persist && (n.status !== status || upgraded || JSON.stringify(n[field]?.changed) !== JSON.stringify(changed))) store.put(next);
