193	    }
194	    // a contradicted note stays stale with no code change: only its verification clears it
195	    if (n.contradicted) {
196	      const next = { ...n, status: 'stale', stale: { since: n.stale?.since || n.recheck?.since || new Date().toISOString(), changed: [] } };
197	      delete next.recheck;
198	      if (persist && (n.status !== 'stale' || n.recheck || n.stale?.changed?.length)) store.put(next);
199	      return next;
