210	// Ask a small model which candidate notes would actually save work on this
211	// task. Returns the subset of ranked entries it picked (order preserved).
212	async function rerank(store, ranked, task, file, model) {
213	  const cands = ranked.slice(0, 8);
214	  // a single candidate is judged too: the best of a poor lot is still poor
215	  if (!cands.length) return cands;
216	  const list = cands.map((r, i) => `[${i + 1}] id=${r.note.id} kind=${r.note.kind}\n    title: ${r.note.title}\n    answers: ${(r.note.answers || []).join(' | ')}\n    body: ${r.note.body.slice(0, 350).replace(/\n/g, ' ')}`).join('\n');
217	  const res = await complete({ model, accounting: { store, purpose: 'rerank' }, schema: RERANK_SCHEMA, maxTokens: 300,
218	    system: 'You gate which cached notes about a codebase get injected into a coding agent\'s context at the start of a task. Injecting an irrelevant note costs tokens and misdirects the agent; injecting a relevant one saves it from re-exploring. Pick only notes whose content directly bears on what the task must touch or understand. Prefer one precise note over several loosely related ones. Picking none is correct when nothing applies.',
219	    prompt: `TASK: ${task}${file ? `\nCURRENT FILE: ${file}` : ''}\n\nCANDIDATE NOTES:\n${list}\n\nReturn the ids of the notes worth injecting (0-3).` });
220	  const pick = new Set((res.json?.useful || []).map(x => String(x).replace(/^\[?(\d+)\]?$/, (_, i) => cands[Number(i) - 1]?.note.id || x).replace(/^id=/, '')));
