502	// too-few-notes (it does not ask a cache below its serving threshold, ops.js:servesNotes) and held-out.
503	export const EMPTY_REASONS = ['too-few-notes', 'held-out', 'all-served', 'no-match', 'only-stale', 'ranker-rejected', 'below-floor'];
504	function emptyReason({ cached, notes, lexical, ranked, ce, freshOnly }) {
505	  if (!notes.length) return cached ? 'all-served' : 'too-few-notes';
506	  if (!lexical.length) return 'no-match';                                   // no note shares the request's terms
