523	// --- implicit feedback ---------------------------------------------------
524	// Apply the distiller's assessment of notes that were injected into a session.
525	// confirmed: the trace shows the agent used the pointer and nothing contradicted it.
526	// contradicted: the trace shows a claim was wrong; body is replaced by the correction.
527	// unused: served but not acted on; repeated unused servings decay confidence.
528	export function attest(store, assessments, { session, client, model } = {}) {
529	  const applied = [];
530	  for (const a of assessments || []) {
531	    const n = store.get(a.id); if (!n) continue;
532	    const now = new Date().toISOString();
533	    n.attest = n.attest || { confirmed: 0, contradicted: 0, unused: 0 };
534	    if (a.verdict === 'confirmed') { n.attest.confirmed++; n.confidence = Math.min(1, (n.confidence ?? 0.7) + 0.05); n.verified = now; }
535	    else if (a.verdict === 'contradicted' && n.kind === 'skill') {
536	      // a session found the skill wrong: the issue is recorded on the card and the skill leaves serving
537	      // and audit until its file changes or a person reviews it (skills.js:markSkillBroken)
538	      n.attest.contradicted++;
539	      n.confidence = Math.max(0.05, (n.confidence ?? 0.8) - 0.25);
540	      store.put(n);
