591	  // a section's own approval is logged when its job finishes (runSectionJob), with the pull request it opened
592	  if (changes.length) store.log({ op: 'context-approve', changes: changes.length, saving: changes.reduce((a, c) => a + c.saving, 0), via: viaOf(via) });
