596	// A decision taken back (the page's Revert, `thinker context --revert <n>`): a switched-off tool or skill is turned back
597	// on (harness.js:undoHarness), an output's compression set back to none, a section's file written back as it was when
598	// the file is still what the approval wrote (else the person's later edits would go: git has it), a dismissal
599	// withdrawn so the change is suggested again, a pending pull request closed with its branch deleted (the page's Close
600	// PR), after which the sections are suggested again. The entry stays in the history, marked reverted.
601	const withOthers = siblings => siblings.length ? `, with ${siblings.length === 1 ? 'the other section' : `the ${siblings.length} other sections`} of the same change (${siblings.map(h => h.title.replace(/^.*? · /, '')).join(', ')})` : '';
602	export async function revertDecision(store, id, { now = Date.now(), prs } = {}) {
603	  const st = readState(store), e = (st.history || []).find(h => h.id === id);
604	  if (!e) return { error: 'no such decision' };
605	  if (e.revertedAt) return { error: 'already reverted' };
606	  const u = undoOf(store, e);
607	  if (!u) return { error: e.pr ? `pull request #${e.pr.number} is ${e.pr.state}; nothing to take back` : 'nothing kept to revert this one by' };
608	  if (u.kind === 'pr') {
609	    const { closePr } = prs || await import('./instruction-pr.js');
610	    const r = closePr(store.repo, u.number, { branch: u.branch });
611	    if (r.error) return { error: r.error };
612	    // every section of the pull request is closed with it
613	    const siblings = st.history.filter(h => h !== e && h.pr?.number === u.number && h.pr.state === 'open');
614	    for (const h of [e, ...siblings]) { h.pr.state = 'closed'; h.pr.at = new Date(now).toISOString(); h.result = `Pull request #${u.number} closed without merging: suggested again`; h.revertedAt = h.pr.at; }
615	    writeState(store, st);
616	    store.log({ op: 'context-revert', kind: 'pr', pr: u.number, sections: 1 + siblings.length });
617	    return { said: `${e.title}: pull request #${u.number} closed; suggested again${withOthers(siblings)}` };
618	  }
619	  // a merged pull request is taken back by another: one that reverts its merge, for every section the pull request made
620	  if (u.kind === 'revert-pr') {
621	    const { revertPr } = prs || await import('./instruction-pr.js');
622	    const siblings = st.history.filter(h => h !== e && h.pr?.number === u.number && h.pr.state === 'merged' && !h.revertedAt);
623	    const titles = [e, ...siblings].map(h => h.title.replace(/^.*? · /, ''));
624	    const r = revertPr(store.repo, { number: u.number, mergeCommit: u.mergeCommit, base: u.base, title: titles.length <= 3 ? titles.join(', ') : `${titles.length} sections` }, { now });
625	    if (r.error) return { error: r.error };
626	    const at = new Date(now).toISOString();
627	    for (const h of [e, ...siblings]) { h.revertPr = { number: r.number, url: r.url, branch: r.branch, base: r.base, openedAt: at }; h.result = `Pull request #${r.number} opened to revert #${u.number}`; h.revertedAt = at; }
628	    writeState(store, st);
629	    store.log({ op: 'context-revert', kind: 'revert-pr', pr: u.number, revertPr: r.number, sections: 1 + siblings.length });
630	    return { said: `${e.title}: pull request #${r.number} opened to revert #${u.number}: ${r.url}${withOthers(siblings)}` };
631	  }
632	  if (u.kind === 'off') {
633	    const { undoHarness } = await import('./harness.js');
634	    const r = undoHarness(store, { names: [u.key] });
635	    if (!/^Turned back on/.test(r)) return { error: r };
636	  } else if (u.kind === 'output') {
637	    const { setOutputCompression } = await import('./context-view.js');
638	    setOutputCompression(store, [u.name], u.level || 'off');
639	  } else if (u.kind === 'on') {
640	    const { switchSources } = await import('./context-view.js');
641	    const r = switchSources(store, { labels: [u.label], builtin: Boolean(u.builtin), global: Boolean(u.global) });
642	    if (!/^Switched off here/.test(r) || /Not switched off/.test(r)) return { error: r.replace(/^Not switched off: /, '') };
643	  } else if (u.kind === 'edit') {
644	    for (const f of u.files) { let now; try { now = fs.readFileSync(path.join(store.repo, f.file), 'utf8'); } catch { now = null; } if (now !== f.after) return { error: `${f.file} changed since; git diff shows what to undo by hand` }; }
645	    for (const f of u.files) { const p = path.join(store.repo, f.file); if (f.before == null) fs.rmSync(p, { force: true }); else fs.writeFileSync(p, f.before); }
646	  }
647	  // an edit over several sections is one undo: the file written back reverts every section of the group
648	  const s2 = readState(store), x = s2.history.find(h => h.id === id);
649	  const siblings = u.kind === 'edit' && e.group ? s2.history.filter(h => h !== x && h.group === e.group && !h.revertedAt) : [];
650	  for (const h of [x, ...siblings]) h.revertedAt = new Date(now).toISOString();
651	  writeState(store, s2);
652	  try { fs.rmSync(undoFile(store, e.group || id), { force: true }); } catch {}
653	  store.log({ op: 'context-revert', kind: u.kind, ...(siblings.length ? { sections: 1 + siblings.length } : {}) });
654	  return { said: `${e.title}: ${{ off: 'turned back on from the next session on', on: 'switched off again from the next session on', output: u.level && u.level !== 'off' ? `${u.level} compression again` : 'compression off', edit: 'written back as it was', dismissed: 'suggested again' }[u.kind]}${withOthers(siblings)}` };
655	}
656	// the changes a choice names: "all", or their numbers in the list (1-based), or their keys, each optionally with the
657	// action picked instead of the suggestion after a colon ("3:remove"; `acts` maps keys to actions)
658	// (`acts` maps keys to actions). The page gives keys as a list, read as they are: a key like `output:Read` is not a
659	// choice with an action after its colon.
660	export function pickChanges(changes, choice, acts = {}) {
661	  const w = Array.isArray(choice) ? choice.map(x => [String(x), null]) : String(choice || '').split(',').map(x => x.trim()).filter(Boolean).map(x => { const m = x.match(/^(.*?):([\w-]+)$/); return m && !m[1].includes(':') ? [m[1], m[2]] : [x, null]; });
662	  const all = w.find(([x]) => /^all$/i.test(x));
663	  const at = (c, i) => all ? all : w.find(([x]) => x === String(i + 1) || x === c.key);
664	  return changes.flatMap((c, i) => { const m = at(c, i); if (!m) return []; const chosen = acts[c.key] || m[1]; return [chosen && c.options?.some(o => o.act === chosen) ? { ...c, chosen } : c]; });
665	}
