447	  const rows = parts.flatMap(x => x.p.rows.map(r => ({ ...r, repo: x.repo, repoName: x.name })));
448	  rows.sort((a, b) => String(b.mergedAt).localeCompare(String(a.mergedAt)));
449	  const saved = { cleared: sum(p => p.saved.cleared), reading: sum(p => p.saved.reading), total: sum(p => p.saved.total) };
450	  const agent = sum(p => p.agent);
