1	// Usage history: a summary of the machine's log (see store.js: logFile), the append-only
2	// record of what was served, learned, verified and mined in every repository, with an
3	// estimate of the exploration the served notes saved.
4	//
5	// The estimate counts only servings that the end-of-session assessment marked
6	// `confirmed` (the agent acted on the note and nothing contradicted it). For each,
7	// it takes one read per file the note rests on (at most 5) and the tokens those
8	// reads would have returned (each file capped at what one read returns). Searches
9	// to find the files, and the re-reading of earlier output on every later model
10	// call, are left out of the legacy `saved.tokens` field. `saved.input` adds observed
11	// note lifetime and subtracts carried note text (cache-savings.js); the report and
12	// running session footer use that estimate. Missing lifetime evidence falls back
13	// to one read minus the note text. Neither field is a measurement of avoided work.
14	import fs from 'node:fs';
15	import os from 'node:os';
16	import path from 'node:path';
17	import { isTestMode } from './test-mode.js';
