20	import { estTokens } from './rank.js';
21	import { Store, logFile, adoptLocalLog, repoId } from './store.js';
22	import { sessionModel, sessionTranscriptFile } from './transcripts.js';
23	import { sections, lifetimeRequests, sessionClears, inputSavings } from './cache-savings.js';
24	import { compressionHeader, compressionSaving } from './compression.js';
25	
26	export const FILE_CAP = 6000;   // tokens one read of a large file returns (about 2000 lines)
27	export const MAX_FILES = 5;
28	// Wall clock of one avoided read: the model turn that issues it and takes in the result.
29	// research/bench-history/RESULTS.md measured 2 to 4.5 seconds of wall clock per tool call (click: 15 s over
30	// 3.4 calls; PostHog: 1.1 min less over 31.6 fewer calls), so this too is an estimate.
31	export const SECONDS_PER_READ = 4;
32	
33	// Deps that are not code a session would have read: the agents' own configuration, git's
34	// internals, thinker's own state, and build or run output. Every note must anchor to an
35	// existing file (ops.js:createNote), so a note about the permission classifier or about
36	// duplicate hooks anchors to .claude/settings.local.json for want of anywhere better. Nobody
37	// learns those rules by reading that file: what such a note saves is a wrong action, not a
38	// read. This estimate only counts reading, so it counts them as nothing rather than crediting
39	// a read no session would have made. The notes keep their anchors and are served as before.
40	export const NOT_READING = /^(\.claude|\.codex|\.cursor|\.gemini|\.pi|\.windsurf|\.devin|\.opencode|\.vscode|\.idea|\.factory|\.qwen|\.kiro|\.clinerules|\.cline|\.kilo|\.kilocode|\.augment|\.goose|\.git|\.thinker|node_modules|dist|coverage)\/|^\.github\/(hooks|instructions)\/|^\.mcp\.json$|^bench\/runs\/|\.log$/;
41	export const countsAsReading = f => !NOT_READING.test(String(f || ''));
42	
43	export function savingOf(repo, note) {
44	  let calls = 0, tokens = 0;
45	  for (const f of [...new Set((note?.deps || []).map(d => d.path).filter(Boolean))].slice(0, MAX_FILES)) {
46	    if (!countsAsReading(f)) continue;
47	    try { const st = fs.statSync(path.join(repo, f)); if (!st.isFile()) continue; calls++; tokens += Math.min(Math.ceil(st.size / 3.6), FILE_CAP); } catch {}
48	  }
49	  return { calls, tokens };
50	}
51	
52	export function cacheHitSavings(repo, notes) {
53	  let calls = 0, tokens = 0, uncounted = 0;
54	  const seenFiles = new Set();
55	  for (const n of notes || []) {
56	    for (const f of [...new Set((n?.deps || []).map(d => d.path).filter(Boolean))].slice(0, MAX_FILES)) {
57	      if (seenFiles.has(f)) continue;
58	      seenFiles.add(f);
59	      if (!countsAsReading(f)) { uncounted++; continue; }
60	      try {
61	        const st = fs.statSync(path.join(repo, f));
62	        if (!st.isFile()) continue;
63	        calls++;
64	        tokens += Math.min(Math.ceil(st.size / 3.6), FILE_CAP);
65	      } catch {}
66	    }
67	  }
68	  // A note whose files are not on disk still stands for at least one read. A note anchored
69	  // only to configuration stands for none, so the floor is not given to it: the answer is
70	  // nothing counted, not a guess from the note's own length.
71	  if (!tokens && !uncounted && notes?.length) {
72	    tokens = notes.reduce((sum, n) => sum + Math.max(Math.ceil((n.body || '').length / 3.6) * 4, 300), 0);
73	  }
74	  const seconds = Math.max(calls, tokens ? 1 : 0) * SECONDS_PER_READ;
75	  return { calls, tokens, uncounted, seconds };
76	}
