83	// What the user sees when a summary comes due: everything served since the last one, at the prompts and
84	// while the agent read and edited files. Nothing is known yet about whether the agent acted
85	// on them, so the notice describes the notes and does not say "saved"; in a week on this
86	// repository about 30% of servings were acted on. What was saved is counted after the
87	// session is assessed (summarize, `thinker usage`). The prompt hook says nothing: a line at
88	// every prompt was noise, and so was one at the end of every turn: a summary comes due every
89	// `prompts` prompts and at most once a day (notice-cadence.js), and `prompts` here is how many
90	// have passed since the last one, so the line says what span it covers.
91	export function turnNotice(repo, notes, { input, prompts = 0 } = {}) {
92	  const span = prompts > 1 ? `over the last ${prompts} prompts` : 'this turn';
93	  if (input) return `🧠 thinker: ${notes?.length ? `${notes.length} ${notes.length === 1 ? 'note' : 'notes'} ${span} · ` : ''}estimated input saved this session: ~${formatTokens(input.tokens)} tokens${input.covered ? '' : ' (one-read fallback; no lifetime data)'}`;
94	  const hits = (notes || []).length;
95	  if (!hits) return '';
96	  const { calls, tokens } = cacheHitSavings(repo, notes);
97	  const noun = `${hits} ${hits === 1 ? 'note' : 'notes'} ${span}`;
98	  // Notes that rest only on configuration point at no code to read: say how many there were
99	  // and stop, rather than print `~0 tokens of code` or a figure the note's length invented.
100	  if (!tokens) return `🧠 thinker: ${noun}`;
101	  const files = calls ? `${calls} ${calls === 1 ? 'file' : 'files'}, ` : '';
102	  return `🧠 thinker: ${noun} (pointing at ${files}~${formatTokens(tokens)} tokens of code)`;
103	}
