105	// The context proxy's saving, said the way a cache hit is said (compression.js). Nothing until the clearing
106	// has had a few turns to pay for itself, and nothing at all where no clear happened: a notice describes what
107	// genuinely took place, never what a default might have done.
108	export function compressionNotice(state) {
