118	  const hits = unique.length;
119	  const noun = `${hits} ${hits === 1 ? 'note' : 'notes'} ${prompts > 1 ? `over the last ${prompts} prompts` : 'this turn'}`;
120	  const detail = input ? `*est. input saved this session: ~${formatTokens(input.tokens)} tokens${input.covered ? ', including re-reads' : ', one-read fallback'}*` : tokens ? `*est. savings: ~${formatTokens(tokens)} tokens*` : '';
