156	export const servedFields = (store, notes, text) => {
157	  const tokens = estTokens(text || ''), sizes = new Map(sections(text || '').map(n => [n.id, n.tokens]));
158	  const parts = notes.map(n => sizes.get(n.id) || estTokens(n.body || ''));
