160	  return { tokens, noteTokens: parts.map(n => Math.ceil(n + extra)),
161	    est: notes.map(n => { const s = savingOf(store.repo, n); return [s.calls, s.tokens]; }),
162	    estFiles: notes.map(n => [...new Set((n.deps || []).map(d => d.path).filter(Boolean))].slice(0, MAX_FILES).filter(countsAsReading).flatMap(f => {
163	      try { const st = fs.statSync(path.join(store.repo, f)); return st.isFile() ? [[f, Math.min(Math.ceil(st.size / 3.6), FILE_CAP)]] : []; } catch { return []; }
