188	// The log is parsed once a process for its size and mtime: the page's report over every repository summarized
189	// a dozen checkouts, and each one read and parsed the same 14 MB (a sixth of a second each, 2 s in all).
190	const parsed = new Map(); // file → { stamp, events }
191	const parse = (f, repo) => {
