339	test('cli setup sends installation telemetry in background', async () => {
340	  const tmpRepo = fs.mkdtempSync(path.join(os.tmpdir(), 'thinker-cli-init-repo-'));
341	  const tmpHome = fs.mkdtempSync(path.join(os.tmpdir(), 'thinker-cli-init-home-'));
342	  execFileSync('git', ['init', '-q'], { cwd: tmpRepo });
343	
344	  // Add a sample note to verify note counts
345	  const store = new Store(tmpRepo).init();
346	  store.put({ id: 'note-1', kind: 'location', title: 'Location note', body: 'app.js handles routes' });
347	
348	  const received = [];
349	  const server = http.createServer((req, res) => {
350	    let body = '';
351	    req.on('data', chunk => { body += chunk; });
352	    req.on('end', () => {
353	      try { received.push(JSON.parse(body)); } catch {}
354	      res.writeHead(202, { 'Content-Type': 'application/json' });
355	      res.end(JSON.stringify({ status: 'accepted' }));
356	    });
357	  });
358	
359	  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
360	  const port = server.address().port;
361	
362	  try {
363	    const CLI = path.resolve('src/cli.js');
364	    execFileSync('node', [CLI, 'setup', '--no-build', '--no-mcp', '--no-git-hook', '--no-proxy', '--clients', 'claude', '--repo', tmpRepo], {
365	      env: {
366	        ...process.env,
367	        THINKER_HOME: tmpHome,
368	        HOME: tmpHome, CODEX_HOME: path.join(tmpHome, '.codex'),
369	        // Exercise background delivery only against this isolated loopback server.
370	        THINKER_TEST: '0', THINKER_NO_AUTO_UPDATE: '1',
371	        THINKER_TELEMETRY_URL: `http://127.0.0.1:${port}`,
372	        THINKER_NO_LEARN: '',
373	        THINKER_TELEMETRY: 'on',
374	      },
375	      stdio: 'pipe',
376	    });
377	
378	    // The send is a detached `node cli.js telemetry` of its own, so wait for the process, not a guess at
379	    // its speed: 3 seconds was enough alone and not under the whole suite, where the release run saw none.
380	    const deadline = Date.now() + 30000;
381	    while (!received.length && Date.now() < deadline) {
382	      await new Promise(r => setTimeout(r, 50));
383	    }
384	
385	    assert.equal(received.length, 1, 'telemetry payload should be received');
386	    assert.equal(received[0].event, 'install');
387	    assert.equal(received[0].cacheSize.totalNotes, 1);
388	    assert.equal(received[0].cacheSize.repositoriesCount, 1);
389	    // a CLI spawned by a test never leaves a real hourly job behind (it would report to production)
390	    assert.equal(telemetryScheduleState(tmpHome).type, undefined);
391	    assert.ok(received[0].installId);
392	  } finally {
393	    server.close();
394	    removeTree(tmpRepo);
395	    removeTree(tmpHome);
396	  }
397	});
