542	    // (underscores, spaces, a Windows drive's colon and backslashes too); the older rule here changed
543	    // only "/" and ".", and both are read. CLAUDE_CONFIG_DIR moves the folder.
544	    const projects = path.join(process.env.CLAUDE_CONFIG_DIR || path.join(home, '.claude'), 'projects');
545	    for (const slug of new Set([r.replace(/[\/.]/g, '-'), r.replace(/[^A-Za-z0-9]/g, '-')])) {
546	      const claude = path.join(projects, slug);
547	      for (const f of ls(claude)) if (f.endsWith('.jsonl')) add('claude', path.join(claude, f), f.slice(0, -6));
548	    }
549	    const gemini = path.join(home, '.gemini', 'tmp', crypto.createHash('sha256').update(r).digest('hex'), 'chats');
550	    for (const f of ls(gemini)) if (f.endsWith('.json')) add('gemini', path.join(gemini, f), f.slice(0, -5));
