552	  // Cursor names project folders after the path (shortened with a hash when long);
553	  // the folder records the workspace it belongs to
554	  const roots = new Set([repo, real]);
555	  const slug = r => r.replace(/[^A-Za-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
556	  const cursorRoot = path.join(home, '.cursor', 'projects');
557	  for (const d of ls(cursorRoot)) {
558	    let ws = null; try { ws = JSON.parse(fs.readFileSync(path.join(cursorRoot, d, '.workspace-trusted'), 'utf8')).workspacePath; } catch {}
