26	// A Claude Code transcript with one tool call, on `model`, reporting `usage` on each of its two model turns
27	function transcript(dir, name, { model, usage, mtime, client = 'claude' }) {
28	  const rows = [
29	    { type: 'attachment', attachment: { type: 'prompt_snapshot', systemPrompt: ['You are an agent.'] } },
30	    { type: 'attachment', attachment: { type: 'environment', text: 'cwd is here' } },
31	    { type: 'user', message: { role: 'user', content: 'tidy a' } },
32	    { type: 'assistant', message: { id: 'm1', role: 'assistant', model, usage: usage && { ...usage, output_tokens_details: { thinking_tokens: 40 } }, content: [{ type: 'thinking', thinking: '', signature: 'x'.repeat(172) }, { type: 'tool_use', id: 't1', name: 'Bash', input: { command: 'cat src/a.js' } }] } },
33	    { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 't1', content: 'export const a = 1;\n' }] } },
34	    { type: 'assistant', message: { id: 'm2', role: 'assistant', model, usage, content: [{ type: 'text', text: 'done' }] } },
35	  ];
36	  const file = path.join(dir, `${name}.jsonl`);
37	  fs.writeFileSync(file, rows.map(r => JSON.stringify(r)).join('\n') + '\n');
38	  fs.utimesSync(file, new Date(mtime), new Date(mtime));
39	  return { client, file, session: name, mtime };
40	}
