286	  const T0 = Date.parse('2026-10-01T00:00:00Z'), H = 3600_000;
287	  const row = (h, x) => ({ t: T0 + h * H, input: 10000, prompts: 1, parts: { instructions: 0, custom: 0, builtin: 0, outputs: 0 }, calls: 10, files: ['AGENTS.md'], sources: {}, outputs: {}, ...x });
