289	  const at = h => new Date(T0 + h * H).toISOString(), now = T0 + 30 * H;
290	  // the thing's cost in a session: a section its tokens on that side times the calls where the file was read; a source
291	  // what the session loaded it at; a tool's outputs what they cost; a section without recorded tokens cannot be costed
292	  const sec = { kind: 'section', key: 'section:AGENTS.md:x', file: 'AGENTS.md', tokens: { before: 300, after: 0 }, at: at(5), decision: 'applied after review' };
293	  assert.equal(itemCost(sec, rows[0], 'before'), 3000); assert.equal(itemCost(sec, rows[1], 'before'), 0, 'the file was not read'); assert.equal(itemCost(sec, rows[3], 'after'), 0);
294	  assert.equal(itemCost({ ...sec, tokens: { before: 300, after: 100 } }, rows[3], 'after'), 2000);
295	  assert.equal(itemCost({ kind: 'section', key: 'section:AGENTS.md:x', at: at(5) }, rows[0], 'before'), null);
296	  assert.equal(itemCost({ kind: 'tool', key: 'claude:tool:Workflow' }, rows[0], 'before'), 4000); assert.equal(itemCost({ kind: 'tool', key: 'claude:tool:Workflow' }, rows[2], 'after'), 0);
297	  assert.equal(itemCost({ kind: 'output', key: 'output:Bash:grep' }, rows[0], 'before'), 9000);
298	  assert.equal(itemCost({ kind: 'output', key: 'output:Bash:grep' }, { outputs: { 'Bash:grep@moderate': 400, 'Bash:grep': 100, 'Bash:grepx': 5 } }, 'after'), 500, 'a compressed tool\'s key carries its level');
299	  // the section removed at hour 5 (one prompt a session here): 1,500 a prompt before (3,000 and 0), 0 since, over 3 prompts
300	  const f = actionEffect(sec, rows, now);
301	  assert.deepEqual([f.before.sessions, f.after.sessions, f.before.prompts, f.after.prompts, f.before.perPrompt, f.after.perPrompt, f.delta, f.window, f.few, f.to], [2, 3, 2, 3, 1500, 0, 1500, 4500, true, null]);
302	  // the share is of what a whole prompt cost before the decision (10,000 input a prompt here), not of the thing's own size
303	  assert.deepEqual([f.whole.before, f.whole.after, f.share], [10000, 10000, 0.15]);
304	  // per prompt: the side's sum over its prompts, so a session of many calls weighs by them (the first session 4 prompts: 3,000 over 5)
305	  const fp = actionEffect(sec, rows.map((r, i) => i === 0 ? { ...r, prompts: 4 } : r), now);
306	  assert.deepEqual([fp.before.prompts, fp.before.perPrompt, fp.window], [5, 600, 1800]);
307	  // the totals: a side's sum, and over the prompts since what the thing would have cost at the before rate against as it was
308	  assert.deepEqual([f.before.total, f.after.total, f.since], [3000, 0, { prompts: 3, atBefore: 4500, total: 0 }]);
309	  // the tool switched off at hour 5: 4,000 a prompt before; since, one of three sessions still loaded it (2,000 → 667)
310	  const tool = { kind: 'tool', key: 'claude:tool:Workflow', at: at(5), decision: 'approved' };
311	  const g = actionEffect(tool, rows, now);
312	  assert.deepEqual([g.before.perPrompt, g.after.perPrompt, g.delta, g.window, g.share], [4000, 667, 3333, 10000, 0.3333]);
313	  assert.equal(g.since.atBefore - g.since.total, g.window, 'the window is exactly the gap: 12,000 at the before rate against 2,000');
314	  // the output compressed at hour 5: 4,500 a prompt before (9,000 and 0), 333 since
315	  const out = actionEffect({ kind: 'output', key: 'output:Bash:grep', at: at(5), decision: 'approved' }, rows, now);
