339	// ---- Pull requests on the Report: what was shipped here and how much of it thinker paid for ----
340	const pr = (n, { merged, agent = 0, cleared = 0, reading = 0, sessions = 1, complete = true, title = `PR ${n}` } = {}) => ({
341	  number: n, title, url: `https://example.test/${n}`, mergedAt: merged,
342	  sessions: Array.from({ length: sessions }, (_, i) => ({ id: `s${n}-${i}` })),
343	  tokens: { agent, prompts: 10, unknownSessions: 0, complete },
344	  saved: { cleared, reading: { calls: 0, tokens: reading, servings: 0 }, total: cleared + reading },
345	});
346	const delivery = (prs, over) => {
347	  const merged = prs.filter(p => p.mergedAt && p.sessions.length);
348	  const sum = f => merged.reduce((a, p) => a + f(p), 0);
349	  const mid = xs => { const v = xs.slice().sort((a, b) => a - b); return v.length ? v[v.length >> 1] : null; };
350	  return { prs, summary: {
351	    merged: merged.length, mergedSeen: prs.filter(p => p.mergedAt).length, mergedAssisted: merged.filter(p => p.saved.total > 0).length,
352	    open: 0, worked: prs.filter(p => p.sessions.length).length,
353	    saved: { cleared: sum(p => p.saved.cleared), reading: sum(p => p.saved.reading.tokens), total: sum(p => p.saved.total) },
354	    tokens: { agent: sum(p => p.tokens.agent), complete: merged.filter(p => p.tokens.complete).length },
355	    medianSavedPerMergedPr: mid(merged.map(p => p.saved.total)), medianTokensPerMergedPr: mid(merged.map(p => p.tokens.agent)), medianHoursToMerge: 2,
356	    sessions: { linked: sum(p => p.sessions.length), unlinked: 4 },
357	    ...over,
358	  } };
359	};
