460	// From a hook: start catch-up in the background, at most every ten minutes.
461	// Only sessions quiet for LEARN_IDLE_MIN minutes: one still running is distilled when it ends or goes quiet.
462	const LEARN_IDLE_MIN = 20;
463	
464	export function learnInBackground(ctx, client, { maintain = true } = {}) {
465	  const { repo, store, sessionLearning, HERE, NO_LEARN } = ctx;
466	  if (isTestMode() || NO_LEARN || !sessionLearning()) return;
467	  const mark = path.join(store.dir, 'state', 'learn.last');
468	  try { if (Date.now() - fs.statSync(mark).mtimeMs < 10 * 60_000) return; } catch {}
469	  fs.mkdirSync(path.dirname(mark), { recursive: true }); fs.writeFileSync(mark, '');
470	  const args = ['learn', '--quiet', '--days', '2', '--max', '5', '--idle-min', String(LEARN_IDLE_MIN), ...(maintain ? ['--maintain'] : []), '--repo', repo];
471	  // inside a desktop app no agent CLI runs: the catch-up waits for the app's own session (session-work.js)
472	  const app = desktopApp(subagentHarness(client));
473	  if (app) { markAppSession(store, app); enqueueJob(store, maintain ? 'learn-maintain' : 'learn', args); return; }
474	  spawn('node', [path.join(HERE, 'cli.js'), 'learn', '--quiet', '--days', '2', '--max', '5', '--idle-min', String(LEARN_IDLE_MIN), ...(maintain ? ['--maintain'] : []), '--repo', repo], { detached: true, stdio: 'ignore', env: { ...process.env, THINKER_LLM_PREFER: client === 'agy' ? 'gemini' : client } }).unref();
