194	    const probed = path.join(m.root, 'probed'), release = path.join(m.root, 'release'), owner = path.join(m.root, 'pid');
195	    fs.writeFileSync(child, `
196	      import net from 'node:net';
197	      import fs from 'node:fs';
198	      import { recordProxyListening } from ${JSON.stringify(pathToFileURL(path.join(path.dirname(CLI), 'proxy-service.js')).href)};
199	      fs.writeFileSync(${JSON.stringify(owner)}, String(process.pid));
200	      const server = net.createServer(socket => { socket.end(); fs.writeFileSync(${JSON.stringify(probed)}, 'yes'); });
201	      server.listen(${port}, '127.0.0.1', () => {
202	        const timer = setInterval(() => {
203	          if (!fs.existsSync(${JSON.stringify(release)})) return;
204	          clearInterval(timer);
205	          recordProxyListening(${port});
206	        }, 10);
207	      });
