213	    pid = Number(fs.readFileSync(owner, 'utf8'));
214	    assert.equal(await Promise.race([
215	      pending.then(() => 'returned'),
216	      new Promise(resolve => setTimeout(() => resolve('waiting'), 100)),
217	    ]), 'waiting', 'a listening socket alone must not finish startup');
