223	  } finally {
224	    // Release a delayed child even when an assertion failed, then stop only that fixture.
225	    fs.writeFileSync(path.join(m.root, 'release'), 'yes');
226	    await pending;
227	    pid ||= Number(fs.existsSync(path.join(m.root, 'pid')) && fs.readFileSync(path.join(m.root, 'pid'), 'utf8'));
