1	// The context proxy (proxy.js) as a service of this machine: on by default since 2026-10-24, the owner's decision.
2	//
3	// `thinker connect` (so the installer and `setup`) picks a free port once, keeps it in THINKER_HOME/state/proxy-service.json,
4	// starts `thinker proxy --port <port>` and keeps it running (a LaunchAgent with KeepAlive on macOS, a systemd user unit on
5	// Linux, and everywhere the prompt hook, which starts it again when nothing listens on the port: a wired base URL with no
6	// listener would break every session, and the hook is the one thing that runs before each model call; that is the exception
7	// to the rule that the hooks do nothing but the cache's work), and writes the proxy's URL where each agent that speaks the
8	// Messages API at a settable base URL reads it: Claude Code's `env.ANTHROPIC_BASE_URL` in `~/.claude/settings.json` (the CLI
9	// and the IDE extensions; the desktop app sets the variable itself and ignores the file), pi's
10	// `providers.anthropic.baseUrl` in `~/.pi/agent/models.json`, OpenCode's `provider.anthropic.options.baseURL` in
11	// `opencode.json`. A person already routing elsewhere is left alone and told: a base URL of their own, or Claude Code on
12	// Bedrock, Vertex or Foundry (those routes do not speak the Messages format). `thinker proxy off` takes it all out,
13	// `thinker proxy on` puts it back, `thinker uninstall --user` removes it with the rest of the wiring.
14	// Codex joins this service by default (owner's request, 2026-10-25): --codex adds a
15	// fixed OpenAI/ChatGPT Responses route, and proxy-codex.js selects the managed provider.
16	//
17	// The service runs with a holdout share (SERVICE_HOLDOUT, 15% of sessions, as the hooks' notes have since 2026-10-04) so
18	// that `thinker proxy report` compares the two sides on the machine's own work; `proxy: { holdout, trigger, keep, keepMin,
19	// clearAtLeast }` in THINKER_HOME/config.json changes the service's flags (holdout 0: none).
20	import fs from 'node:fs';
21	import os from 'node:os';
22	import path from 'node:path';
23	import net from 'node:net';
24	import { spawn, execFileSync } from 'node:child_process';
25	import { thinkerHome } from './update.js';
26	import { readMachineConfig } from './repo-switch.js';
27	import { isTestMode } from './test-mode.js';
28	import { wireCodexProxy } from './proxy-codex.js';
29	import { routeEvidence, ownGateway, cloudOn, isAnthropicHost, CLOUD_VARS, BASE_URL_VAR } from './proxy-route.js';
30	
31	export const SERVICE_HOLDOUT = 0.15;
32	export const PROXY_LABEL = 'com.thinker.proxy';
33	export const PROXY_ENV = BASE_URL_VAR;
34	// Claude Code on a cloud route speaks that provider's format, which the proxy does not read
35	export const OTHER_ROUTES = CLOUD_VARS;
36	
37	const stateFile = home => path.join(home, 'state', 'proxy-service.json');
38	const readJson = (f, d = {}) => { try { return JSON.parse(fs.readFileSync(f, 'utf8')) || d; } catch { return d; } };
39	const writeJson = (f, v) => { fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, JSON.stringify(v, null, 2) + '\n'); };
40	// Only transport settings belong in the service environment, never a model API key. Keep the
41	// shell's settings across launchd/systemd restarts; Claude's env block may supply them too.
42	const NETWORK_KEYS = ['HTTP_PROXY', 'HTTPS_PROXY', 'ALL_PROXY', 'NO_PROXY', 'http_proxy', 'https_proxy', 'all_proxy', 'no_proxy', 'NODE_EXTRA_CA_CERTS', 'SSL_CERT_FILE', 'SSL_CERT_DIR'];
43	export function serviceNetworkEnv(home = thinkerHome(), env = process.env) {
44	  const settings = (!isTestMode() || env.CLAUDE_CONFIG_DIR) ? readJson(path.join(env.CLAUDE_CONFIG_DIR || path.join(os.homedir(), '.claude'), 'settings.json')).env : {};
45	  const pick = e => Object.fromEntries(NETWORK_KEYS.filter(k => typeof e?.[k] === 'string').map(k => [k, e[k]]));
46	  return { ...pick(serviceState(home).networkEnv), ...pick(settings), ...pick(env) };
47	}
48	function saveNetworkEnv(home, env) {
49	  writeJson(stateFile(home), { ...serviceState(home), networkEnv: serviceNetworkEnv(home, env) });
50	  fs.chmodSync(stateFile(home), 0o600); // a proxy URL can carry transport credentials
51	}
52	// Only a process that successfully bound the service's port may claim to be the running service.
53	export function recordProxyListening(port, { home = thinkerHome(), pid = process.pid } = {}) {
54	  const s = serviceState(home);
55	  if (!s.enabled || s.port !== port) return;
56	  writeJson(stateFile(home), { ...s, pid, startedAt: new Date().toISOString(), args: serviceArgs(home, s).join(' '), version: appVersion() });
57	}
58	// An agent's own file, read in order to write it back. `readJson` answers `{}` for anything it cannot parse, and
59	// writing that back replaced a whole settings file -- permissions, hooks, model, every env of the person's -- with
60	// thinker's one key. A file with a comment in it, a trailing comma, or one caught half-written by another process
61	// is left exactly as it is and named instead. An absent or empty file is a new one and is fine to write.
62	const readForWrite = f => {
63	  let text;
64	  try { text = fs.readFileSync(f, 'utf8'); } catch { return { value: {} }; }
65	  if (!text.trim()) return { value: {} };
66	  try { const v = JSON.parse(text); return { value: v && typeof v === 'object' ? v : {} }; }
67	  catch { return { why: `${path.basename(f)} is not valid JSON, so thinker left it alone` }; }
68	};
