70	// { enabled, port, ports (every port the service ever had, so an old URL is still known as ours), since, off, pid }
71	export const serviceState = (home = thinkerHome()) => readJson(stateFile(home));
72	export const proxyOn = (home = thinkerHome()) => serviceState(home).enabled === true;
73	export const urlFor = port => `http://127.0.0.1:${port}`;
74	export const proxyUrl = (home = thinkerHome()) => { const s = serviceState(home); return s.port ? urlFor(s.port) : null; };
75	const ownUrls = (home, s = serviceState(home)) => new Set([...(s.ports || []), s.port].filter(Boolean).map(urlFor));
76	const trimUrl = v => String(v || '').replace(/\/+$/, '');
77	// Where the proxy sends what it receives. The default is Anthropic's API; a person who routes Claude Code
78	// through a model server of their own can have the proxy sit in front of that instead (`thinker proxy on
79	// --gateway`, the question in proxy-offer.js), which is the only way the clearing reaches those sessions at all.
80	// Kept in the service's own state rather than written into the machine's config.json, which is the person's file;
81	// `proxy: { upstream }` there still wins for anyone who set it by hand. Anthropic's own host is the default
82	// and never a gateway (proxy-route.js:isAnthropicHost): a state that holds it -- written by a yes to the repair
83	// question on 2026-11-01, when the desktop app's own ANTHROPIC_BASE_URL was taken for a model server -- reads
84	// as no upstream, so the flags, the status line and `isOwnRoute` all say the ordinary route.
85	export const proxyThrough = (home = thinkerHome()) => { const u = readMachineConfig(home).proxy?.upstream || serviceState(home).upstream || null; return u && !isAnthropicHost(u) ? u : null; };
86	// A route of the person's own that the proxy forwards to is not a reason to leave their settings alone: pointing
87	// the agent at the proxy keeps every request going to the same place, with the same credentials, plus the edit.
88	export const isOwnRoute = (value, home = thinkerHome()) => isOwnUrl(value, home) || (!!value && trimUrl(value) === trimUrl(proxyThrough(home)));
89	// a URL this machine's service had, trailing slash or not
90	export const isOwnUrl = (value, home = thinkerHome()) => !!value && ownUrls(home).has(String(value).replace(/\/+$/, ''));
91	export const logFile = (home = thinkerHome()) => path.join(home, 'state', 'proxy-service.log');
92	// where the proxy writes a line per request it passes (proxy.js:startProxy); `thinker proxy report` and the
93	// telemetry's proxy block read it
94	export const proxyLogFile = (home = thinkerHome(), env = process.env) => env.THINKER_PROXY_LOG || path.join(home, 'state', 'proxy.jsonl');
95	
96	export function freePort() {
97	  return new Promise((resolve, reject) => {
98	    const s = net.createServer();
99	    s.once('error', reject);
100	    s.listen(0, '127.0.0.1', () => { const { port } = s.address(); s.close(() => resolve(port)); });
101	  });
102	}
103	
104	// up to `wait` ms for something to listen on the port
105	export async function waitListening(port, wait, { step = 50, ready = () => true } = {}) {
106	  const t0 = Date.now();
107	  while (Date.now() - t0 < wait) { if (await isListening(port, { timeout: 200 }) && ready()) return true; await new Promise(r => setTimeout(r, step)); }
108	  return await isListening(port, { timeout: 200 }) && ready();
109	}
110	
111	// The OS accepts connections before the child's `listening` callback has recorded its
112	// ownership. Wait for both: `off` needs the PID, and the next hook needs the flags and
113	// version to avoid restarting a process that has only just started. A detached child
114	// that failed to bind must not borrow readiness from some other listener on the port.
115	function waitProxyStarted(home, port, wait, pid) {
116	  const args = serviceArgs(home).join(' '), version = appVersion();
117	  return waitListening(port, wait, { ready: () => {
118	    const s = serviceState(home);
119	    return s.enabled === true && s.port === port && Number.isSafeInteger(s.pid) && s.pid > 0 &&
120	      (pid === undefined || s.pid === pid) && s.args === args && s.version === version;
121	  } });
122	}
123	
124	export function isListening(port, { timeout = 400 } = {}) {
125	  return new Promise(resolve => {
126	    if (!port) return resolve(false);
127	    const c = net.connect({ port, host: '127.0.0.1' });
128	    const done = v => { try { c.destroy(); } catch {} resolve(v); };
129	    c.setTimeout(timeout, () => done(false));
130	    c.once('connect', () => done(true));
131	    c.once('error', () => done(false));
132	  });
133	}
134	
135	// the service's flags: the port, the holdout, and what THINKER_HOME/config.json's `proxy` block sets
136	export function serviceArgs(home = thinkerHome(), state = serviceState(home)) {
137	  const cfg = readMachineConfig(home).proxy || {};
138	  const holdout = cfg.holdout == null ? SERVICE_HOLDOUT : Number(cfg.holdout) || 0;
139	  const args = ['proxy', '--port', String(state.port), '--holdout', String(holdout), '--codex'];
140	  const upstream = proxyThrough(home);
141	  for (const [key, flag] of [['trigger', '--trigger'], ['keep', '--keep'], ['keepMin', '--keep-min'], ['clearAtLeast', '--clear-at-least']]) if (cfg[key] != null) args.push(flag, String(cfg[key]));
142	  if (upstream) args.push('--upstream', String(upstream));
143	  // on by default (proxy.js:PROXY_DEFAULTS, 2026-10-28); a machine config that says false keeps that clear off
144	  for (const [key, flag] of [['clearInputs', 'clear-inputs'], ['clearThinking', 'clear-thinking'], ['clearDeep', 'clear-deep']]) {
145	    if (cfg[key] === false) args.push(`--no-${flag}`);
146	    else if (cfg[key] === true) args.push(`--${flag}`);
147	  }
148	  return args;
149	}
