151	// the proxy as a detached process (the hook's way, and the only one where no service manager runs); the pid is kept so
152	// `off` can stop it
153	// The version of the copy this process runs from, recorded with the flags a running proxy was started with
154	export const appVersion = () => { try { return JSON.parse(fs.readFileSync(new URL('../package.json', import.meta.url), 'utf8')).version || null; } catch { return null; } };
155	
156	export function startDetached({ cli, home = thinkerHome() }) {
157	  if (process.env.CODEX_SANDBOX_NETWORK_DISABLED === '1') return null;
158	  saveNetworkEnv(home, process.env);
159	  const s = serviceState(home);
160	  if (!s.port) return null;
161	  fs.mkdirSync(path.dirname(logFile(home)), { recursive: true });
162	  const fd = fs.openSync(logFile(home), 'a');
163	  const child = spawn(process.execPath, [cli, ...serviceArgs(home, s)], { detached: true, stdio: ['ignore', fd, fd], env: { ...process.env, ...serviceNetworkEnv(home), THINKER_HOME: home } });
164	  child.unref();
165	  try { fs.closeSync(fd); } catch {}
166	  return child.pid;
167	}
