169	// From the prompt hook on every prompt: nothing when the service is off or already listening (one connect, under a
170	// millisecond); else the proxy is started and given `wait` ms to listen before the hook returns, so the agent's next
171	// model call finds it.
172	export async function ensureProxy({ cli, home = thinkerHome(), wait = 1500, restartFn = restartService } = {}) {
173	  const s = serviceState(home);
174	  if (!s.enabled || !s.port) return { on: false };
175	  // the setting taken out by hand is an answer, and this is the first thing that runs after it: the service goes,
176	  // rather than the URL being written in again on the next update (`removedByHand`)
177	  const gone = trackClaude({ home }) || removedByHand({ home }) || routeAppeared({ home });
178	  if (gone) { standDown(gone, { home }); return { on: false, stoodDown: gone }; }
179	  if (await isListening(s.port)) {
180	    // A running proxy keeps the flags, the routes and the code it was started with, and nothing replaced it: this
181	    // function only ever started one when none was listening. So a new clearing policy, a `--gateway` upstream or
182	    // a route added to the proxy reached nobody until the process happened to die. On this machine a proxy from
183	    // 2026-10-24 served 0.2.11's flags for four days -- no `/codex` route, so every Codex model call answered 404.
184	    // The prompt hook is the quiet moment to replace it: between turns, with no request of the agent's in flight.
185	    // A state without the record (every machine, the first time this runs) counts as different, so each is
186	    // replaced once and picks up the present policy.
187	    const want = serviceArgs(home, s).join(' ');
188	    const version = appVersion();
189	    if (s.args === want && s.version === version) return { on: true, running: true };
190	    const why = s.args === undefined ? 'the first run that records them' : s.version !== version ? `a new version (${s.version || 'unknown'} -> ${version})` : 'the flags changed';
191	    // Let the installed service manager own the process. Starting a detached competitor here
192	    // caused repeated EADDRINUSE crashes, and could inherit the invoking agent's network sandbox.
193	    saveNetworkEnv(home, process.env);
194	    if (restartFn({ cli, home, managedOnly: true })) {
195	      const listening = await waitProxyStarted(home, s.port, wait);
196	      return { on: true, restarted: true, why, managed: true, listening };
197	    }
198	    if (process.env.CODEX_SANDBOX_NETWORK_DISABLED === '1') return { on: true, running: true, deferred: 'network-restricted hook' };
199	    if (s.pid) { try { process.kill(s.pid, 'SIGTERM'); } catch {} }
200	    const pid = startDetached({ cli, home });
201	    const listening = await waitProxyStarted(home, s.port, wait, pid);
202	    return { on: true, restarted: true, why, pid, listening };
203	  }
204	  saveNetworkEnv(home, process.env);
205	  if (restartFn({ cli, home, managedOnly: true })) {
206	    const listening = await waitProxyStarted(home, s.port, wait);
207	    return { on: true, started: true, managed: true, listening };
