563	  return { port, url: urlFor(port), service, wired, listening, upstream: upstream || null, gatewayFrom: found?.where || null };
564	}
565	// `thinker proxy off`, `uninstall --user`: the agents' files first (a session started now goes straight to the API),
566	// then the service
567	export function disableProxyService({ home = thinkerHome(), manage, keepState = true } = {}) {
568	  const wired = wireAgents(null, { home });
569	  const removed = uninstallService({ home, manage });
570	  const s = serviceState(home);
571	  // the version that turned it off, so the one-off offer can tell someone who turned it off while the fault of
572	  // 2026-10-28 was live from someone who turned it off on a version that already behaves (proxy-offer.js)
573	  if (keepState) writeJson(stateFile(home), { ...s, enabled: false, off: new Date().toISOString(), offVersion: appVersion(), pid: undefined, wroteClaude: undefined, upstream: undefined });
574	  else fs.rmSync(stateFile(home), { force: true });
575	  return { wired, removed };
576	}
577	
578	// one line per agent for the commands' output
579	export function wiredLines(wired, url, upstream = null, { hint = true, home = thinkerHome(), env = process.env, repos = [] } = {}) {
580	  const lines = [];
581	  const names = { claude: 'Claude Code', pi: 'pi', opencode: 'OpenCode', codex: 'Codex' };
582	  for (const c of wired.changed) lines.push(`${names[c.agent]}: ${url ? `model calls go through the proxy (${url}${upstream ? ` on to ${upstream}` : ''}, ${c.file})` : `the proxy's URL taken out of ${c.file}`}`);
583	  for (const s of wired.skipped) lines.push(`${names[s.agent]}: left as it is, ${s.reason}`);
584	  // An agent left alone because it is routed somewhere of the person's own is a dead end without this: the
585	  // reason says what thinker saw and nothing says what to do about it (2026-10-28).
586	  if (hint && url && wired.skipped.length) { const h = gatewayHint({ home, env, repos }); if (h) lines.push(h); }
587	  return lines;
588	}
589	
590	// What to tell someone whose agent is routed through a model server of their own. Worked out from this machine,
591	// not parsed out of a blocker's message: a cloud route cannot be helped, a gateway that speaks the Messages API
592	// can, and the proxy never goes in front of one unasked (enableProxyService). null when there is nothing to say.
593	export function gatewayHint({ home = thinkerHome(), env = process.env, repos = [] } = {}) {
594	  for (const k of CLOUD_VARS) if (cloudOn(env[k])) return `Claude Code runs on ${k.replace('CLAUDE_CODE_USE_', '').toLowerCase()}, which does not take the API's context-management edit, so the proxy cannot clear old tool results in those sessions.`;
595	  const found = ownGateway({ env, repos, isOwn: u => isOwnRoute(u, home) });
596	  if (!found?.url) return null;
597	  return 'A model server of your own is the route: `thinker proxy on --gateway` puts the proxy in front of it instead of the API, which is how the clearing reaches those sessions. The requests keep going to the same place with the same credentials.';
598	}
