40	// A Claude Code transcript: each call one model turn, the tool's result in the next user message.
41	function transcript(dir, name, calls, { mtime } = {}) {
42	  const rows = [{ type: 'user', message: { role: 'user', content: 'tidy the api views' } }];
43	  calls.forEach(([tool, input, result], i) => {
44	    rows.push({ type: 'assistant', message: { id: `m${i}`, role: 'assistant', model: 'claude-x', usage: { input_tokens: 10, output_tokens: 1 }, content: [{ type: 'tool_use', id: `t${i}`, name: tool, input }] } });
45	    rows.push({ type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: `t${i}`, content: result || 'ok' }] } });
46	  });
47	  rows.push({ type: 'assistant', message: { id: 'end', role: 'assistant', usage: { input_tokens: 10, output_tokens: 1 }, content: [{ type: 'text', text: 'done' }] } });
48	  const file = path.join(dir, `${name}.jsonl`);
49	  fs.writeFileSync(file, rows.map(r => JSON.stringify(r)).join('\n') + '\n');
50	  if (mtime) fs.utimesSync(file, new Date(mtime), new Date(mtime));
51	  return { client: 'claude', file, session: name, mtime: mtime || Date.now() - 3600_000 };
52	}
