338	  const { allChanges } = await import('../src/context-suggest.js');
339	  // One repository compressed `cat` a week ago: its uncompressed row is a dead period there (`past`), what it cost
340	  // unrecoverable. The other never compressed it, so its uncompressed row is live and worth compressing.
341	  const out = (over) => ({ name: 'Bash:cat', kind: 'output', compressible: true, tokens: 500, perCall: 500, calls: 10, usedIn: 4, ...over });
342	  const view = (sessions, tools) => ({ days: 30, sessions, prompts: sessions, totals: { outputs: { tokens: 10, perPrompt: 10, window: 10 * sessions } },
343	    skills: [], tools: [], instructions: { file: null, sections: [] }, timeline: [], outputs: { sessions, prompts: sessions, tools } });
344	  const compressed = view(10, [
345	    out({ key: 'Bash:cat', level: null, past: true, compression: 'moderate', sessions: 7, prompts: 700, window: 7_000_000, wastedWindow: 3_000_000, saveModerateWindow: 2_000_000 }),
346	    out({ key: 'Bash:cat@moderate', level: 'moderate', past: false, compression: 'moderate', sessions: 3, prompts: 300, window: 30_000, wastedWindow: 9_000, saveModerateWindow: 1_000 }),
347	  ]);
348	  const never = view(10, [out({ key: 'Bash:cat', level: null, past: false, compression: null, sessions: 10, prompts: 1_000, window: 500_000, wastedWindow: 200_000, saveModerateWindow: 300_000 })]);
349	  const v = mergeViews([{ repo: 'a', name: 'A', view: compressed }, { repo: 'b', name: 'B', view: never }]);
350	  const rows = v.outputs.tools.filter(t => t.name === 'Bash:cat');
351	  assert.equal(rows.length, 3, 'the dead uncompressed period, the live uncompressed one, and the compressed one');
352	  const dead = rows.find(t => t.past && !t.level), live = rows.find(t => !t.past && !t.level), now = rows.find(t => t.level === 'moderate');
353	  // an output row carries no repository: the page applies one to every repository on the machine (page.html), so the
354	  // figures are what matters -- the dead period keeps the one repository's own and never absorbs the live one
355	  assert.deepEqual([dead.window, dead.sessions, dead.prompts], [7_000_000, 7, 700]);
356	  assert.deepEqual([live.window, live.sessions, live.prompts], [500_000, 10, 1_000]);
357	  assert.deepEqual([now.window, now.past], [30_000, false]);
358	  // a live row's setting is its own level, so the action offered and the saving beside it are the same thing
359	  assert.deepEqual([live.compression, now.compression], [null, 'moderate']);
360	  // the dead period is offered no action and counts towards no saving: before 2026-10-26 `every` made this row live,
361	  // and the machine's top output suggestion was the 2M of a tool already compressed, to be uncompressed
362	  const changes = allChanges(v).filter(c => c.kind === 'output' && c.title.startsWith('cat'));
363	  assert.deepEqual(changes.map(c => [c.default?.act, c.total]), [[ 'compress', 300_000 ], [ 'uncompress', 1_000 ]]);
