1	// What each section of a repository's instruction file (AGENTS.md, or CLAUDE.md) is worth, measured on the
2	// sessions agents ran here: what it costs (its tokens, read again on every model call of every session) against
3	// how often it bore on the work and whether the agent acted on it. A measurement for the person, never a rewrite
4	// of the team's file: what to keep is theirs to decide (a change is a pull request, instruction-edit.js).
5	//
6	//   applied   free, on every session: the session did what the section is about, by the triggers the
7	//             section's own text gives (instruction-sections.js:deriveTriggers): it named or edited a file of
8	//             the section's area, ran the command it is about (a commit, a pull request), or read code it names.
9	//             Replayed from the transcript's tool events. A section with no trigger is never "applied": the
10	//             judge alone says anything about it.
11	//   judged    a model call on a 25% sample of sessions as they end (VALUE.share; `instructions: { value: { judge:
12	//             false, share } }` in .thinker/config.json turns it off or changes the share; `thinker context --judge n`
13	//             judges n more by hand): shown the sections, what the session asked, the
14	//             commands it ran, the files it read and edited and its change, it names the sections that bore on
15	//             the session and says of each whether the agent followed it, went against it, or neither showed.
16	//             Through llm.js:complete, so a desktop app's session answers it (session-llm.js), within the daily
17	//             token cap. Logged as op "instruction-value".
18	//
19	// Kept per session in .thinker/state/instruction-value.json (this checkout's, never shared), by the transcript's
20	// size so a session that grew is read again.
21	import fs from 'node:fs';
22	import path from 'node:path';
23	import { createHash } from 'node:crypto';
24	import { deriveTriggers, sectionFires, codeHits, globRegex as triggerGlob } from './instruction-sections.js';
25	import { diskCache, cacheKey } from './disk-cache.js';
26	import { parseTranscript, findSessions } from './transcripts.js';
27	import { complete, DEFAULT_DISTILL_MODEL } from './llm.js';
28	import { tokensOf } from './model-usage.js';
29	import { isTestMode } from './test-mode.js';
30	import { withinDailyCap } from './maintain.js';
31	import { outcomeSampled, sessionDiff, ruleGlobs, globRegex } from './instruction-evidence.js';
32	import { execFileSync } from 'node:child_process';
33	import { checkouts } from './harness.js';
34	
35	// Leaf sections: a "###" section on its own, a "##" one with the prose before its first "###"; the "#" title apart.
