301	export function valuePrompt(secs, activity, diff) {
302	  let used = 0;
303	  const shown = [];
304	  for (const s of secs) { if (used + s.text.length > VALUE.sectionsChars) break; used += s.text.length; shown.push(`[id: ${s.id}]\n${s.text.trim()}`); }
