306	  const cmds = [...new Set(activity.commands.map(c => cut(c.replace(/\s+/g, ' '), 200)))].slice(-VALUE.commands);
307	  return `INSTRUCTION FILE SECTIONS:\n\n${shown.join('\n\n')}\n\nSESSION\nAsked:\n${activity.prompts.slice(0, 3).map(p => `- ${cut(p, 600)}`).join('\n') || '(nothing recorded)'}\n\nCommands run:\n${cmds.map(c => `- ${c}`).join('\n') || '(none)'}\n\nFiles read: ${activity.read.slice(0, 60).join(', ') || '(none)'}\nFiles edited: ${activity.edited.slice(0, 60).join(', ') || '(none)'}\n\nThe agent's last message:\n${cut(activity.answer, 1500) || '(none)'}\n\nCHANGE${diff.length > VALUE.diffChars ? ` (cut at ${VALUE.diffChars} of ${diff.length} characters)` : ''}:\n${diff.slice(0, VALUE.diffChars) || '(no change in the working tree)'}`;
