341	  store.log({ op: 'instruction-value', session: id, file: src.file, sections: Object.fromEntries(Object.entries(r.verdicts).map(([k, v]) => [k, v.verdict])), tokens: r.tokens ?? undefined, cost: r.cost ?? undefined, metered: true, phase });
