345	// The end-of-session path (commands/learn.js:distillFile): on a share of sessions by their id, when the switch is on.
346	export async function instructionValueCheck(store, file, { session, phase, completeFn = complete, env = process.env } = {}) {
347	  const cfg = valueConfig(store, env);
348	  if (!cfg.judge || !outcomeSampled(session || file, cfg.share)) return null;
349	  return judgeSessionFile(store, file, { session, phase, completeFn });
350	}
351	
352	// Judge `n` sessions not judged yet, sampled over the window (`thinker context --judge n`, the page's button).
353	// A session written to in the last IDLE_MS is still running (this one, or another agent's): judged once it is quiet.
354	export const IDLE_MS = 20 * 60_000;
355	export async function judgeRecent(store, { n = 5, days = 30, completeFn = complete, sessions, onEach, now = Date.now() } = {}) {
356	  const files = instructionFiles(store.repo);
357	  if (!files.length) return { judged: 0, skipped: 'no-file' };
358	  const st = readValueState(store);
359	  sessions ??= findRepoSessions(store.repo, days);
360	  const src = files[0];
361	  let judged = 0, tokens = 0;
362	  // a sample spread over the window (by a hash of the session id), not the newest sessions alone
363	  const order = s => parseInt(createHash('sha1').update(String(s.session)).digest('hex').slice(0, 8), 16);
364	  for (const s of sessions.filter(s => readsFile(src, s.client)).sort((a, b) => order(a) - order(b))) {
365	    if (judged >= n) break;
366	    if (st.sessions[s.session]?.judged || now - s.mtime < IDLE_MS) continue;
367	    const r = await judgeSessionFile(store, s.file, { session: s.session, client: s.client, completeFn, phase: 'manual' });
368	    if (r.skipped === 'daily-cap') return { judged, tokens, skipped: 'daily-cap' };
369	    if (r.skipped) continue;
370	    judged++; tokens += r.tokens || 0; onEach?.(s, r);
371	  }
372	  return { judged, tokens };
373	}
374	
375	// --- the report ----------------------------------------------------------------------------------------------
376	export function findRepoSessions(repo, days) {
377	  return [...new Map(checkouts(repo).flatMap(r => findSessions(r, { sinceMs: days * 86400_000 })).map(s => [s.file, s])).values()].sort((a, b) => b.mtime - a.mtime);
378	}
379	const median = xs => { const a = xs.filter(n => Number.isFinite(n) && n > 0).sort((x, y) => x - y); return a.length ? a[Math.floor(a.length / 2)] : 0; };
380	
381	// Per section over the window: tokens, the model calls that read it (`prompts`), what it cost over the window
382	// (tokens × those calls) and what that is on an average prompt here (`perPrompt`: the window cost over every prompt
383	// of the window, as the Report counts a prompt), the sessions that read it, how many it bore on (applied), and the
384	// judged verdicts with the share followed. `prompts` names the denominator: the caller passes the whole window's
385	// model calls (context-view.js, where the sessions that read no instruction file count too), else this reader's own.
386	export function instructionValue(store, { days = 30, sessions, prompts } = {}) {
387	  const files = instructionFiles(store.repo);
388	  // no instruction file: the same shape, empty, so the Context view of such a repository still renders
389	  if (!files.length) return { file: null, files: [], tokens: 0, sessions: 0, prompts: 0, judged: 0, calls: 0, judge: valueConfig(store), sections: [], timeline: [], savings: { perPrompt: 0, sections: 0, share: 0, window: 0 } };
390	  const secs = valueSections(store, files), srcHash = sha(files.map(f => f.file + f.text).join('\0')), st = readValueState(store);
391	  sessions ??= findRepoSessions(store.repo, days);
392	  const recs = [];
393	  for (const s of sessions) {
394	    if (!files.some(f => readsFile(f, s.client))) continue;
395	    const r = sessionRecord(store, st, s, secs, srcHash, files);
396	    if (r) recs.push({ ...r, session: s.session });
397	  }
398	  writeValueState(store, st);
399	  // sessions recorded before the files were counted read the root file only
400	  const loadedIn = r => r.loaded || [files[0].file];
401	  const reading = recs.filter(r => loadedIn(r).length);
402	  const calls = median(reading.map(r => r.turns)), n = reading.length;
403	  // the window's model calls: every call reads the file again, so a section's cost is its size times the calls that
404	  // carried it, and its share of an average prompt is that over every prompt of the window
405	  const promptsOf = rs => rs.reduce((a, r) => a + Math.max(1, r.turns || 0), 0);
406	  // the denominator is the window's prompts, the caller's where it counts sessions this reader does not see; never
407	  // fewer than the calls that read the files, so no section shows more a prompt than its own size
408	  const mine0 = promptsOf(reading), denom = Math.max(1, prompts || 0, mine0);
409	  const rows = secs.map(s => {
410	    // a section counts in the sessions that read its file: what it costs is averaged over every session
411	    const loaded = reading.filter(r => loadedIn(r).includes(s.file));
412	    // A section changed inside the window (compressed, rewritten, added: sectionAges) is a new section from then: the
413	    // sessions before read another text, so they say nothing about whether this one is used, and what it cost them was
414	    // the old text's size. Its use is measured over the sessions since the change alone, and with fewer than
415	    // RARE.minSessions of them it is too few to say (unknown: not flagged, not suggested) rather than a verdict on one
416	    // or two sessions; what it costs a session is the current text in the share of sessions that read its file, as for
417	    // any section, and over the window it cost that in the sessions since the change (`sessionsSince`).
418	    const recent = s.changedAt != null && reading.some(r => r.mtime < s.changedAt);
419	    const mine = recent ? loaded.filter(r => r.mtime >= s.changedAt) : loaded, judged = mine.filter(r => r.judged);
