421	    const applied = mine.filter(r => r.applied[s.id]).length;
422	    // the prompts that needed it: the model calls that fired its triggers, of every call of the sessions that read it
423	    const appliedPrompts = mine.reduce((a, r) => a + Math.min(Math.max(1, r.turns || 0), r.appliedTurns?.[s.id] || 0), 0);
424	    const v = { followed: 0, violated: 0, applicable: 0 };
425	    for (const r of judged) { const x = r.judged.verdicts[s.id]; if (x) v[x.verdict]++; }
426	    const bore = v.followed + v.violated + v.applicable;
427	    const decided = v.followed + v.violated;
428	    // one rule for every part: its present size in every model call that carried it (a section: the calls of the
429	    // sessions that read its file), and that over every prompt of the window. A section changed inside the window
430	    // keeps that cost -- the change governs what its *use* is measured over (`mine`), not what it costs now.
431	    const promptsHere = promptsOf(loaded), window = s.tokens * promptsHere, perPrompt = Math.round(window / denom);
