447	  for (const r of rows) Object.assign(r, wasteLevel(r, fileCost));
448	  const flagged = rows.filter(r => r.waste === 'high' || r.waste === 'medium');
449	  const savings = { perPrompt: flagged.reduce((a, r) => a + r.wasted, 0), sections: flagged.length };
450	  savings.share = fileCost ? savings.perPrompt / fileCost : 0;
451	  // over the window, each flagged section in the calls that read its present text
452	  savings.window = flagged.reduce((a, r) => a + (r.wastedWindow || 0), 0);
453	  const tok = f => Math.ceil(f.text.length / 4), fileTokens = tok(files[0]);
454	  // per session, for the trend: the tokens of the files it read, read again by each of its model calls (today's
455	  // files: an earlier size is not kept)
456	  // `files`: which instruction files the session read, so the Report can cost one section a session before and since its change (report.js:actionEffect)
457	  const timeline = reading.filter(r => r.turns).map(r => ({ t: r.mtime, session: r.session, client: r.client, calls: r.turns, tokens: files.filter(f => loadedIn(r).includes(f.file)).reduce((a, f) => a + tok(f), 0), files: loadedIn(r) }));
458	  const fileRows = files.map(f => ({ file: f.file, kind: f.kind, tokens: tok(f), loadedIn: reading.filter(r => loadedIn(r).includes(f.file)).length, ...(f.globs?.length ? { globs: f.globs } : {}), ...(f.dir ? { dir: f.dir } : {}) }));
459	  const label = files.length === 1 ? files[0].file : `${files[0].file} + ${files.length - 1} more`;
460	  return { file: label, files: fileRows, tokens: fileTokens, sessions: n, prompts: mine0, denom, judged: judged.length, calls, judge: valueConfig(store), sections: rows, timeline, savings };
461	}
462	
463	// How often sessions acted on a section, and the tokens spent on it in the sessions that did not: from the judge's
464	// verdicts (followed) once enough sessions are judged, else from its triggers (broad: a section about a common path applies
465	// often), else unknown. `wasted` ranks the sections that cost most for least.
466	// Acted on: the judged sessions whose agent followed the section (a verdict of followed), once enough are judged.
467	// A section changed inside the window (`recent`) is measured over the sessions since the change, and fewer than
468	// RARE.minSessions of them say nothing yet.
469	// The share of prompts that needed the section (`usedShare`): the model calls that fired its triggers, of every call of
470	// the sessions that read it. By prompts since 2026-10-25 (the owner's ask); the judge's verdicts stay beside it as the
471	// section's value, not in the share. A section with no trigger, or changed too recently to have been read enough, is
472	// unknown. `wasted` is what it cost on an average prompt where it was not needed, `wastedWindow` the same over the window.
473	export function use({ sessions, prompts, appliedPrompts, triggered, recent = false }, perPrompt, window = null) {
474	  const share = triggered && prompts && !(recent && sessions < RARE.minSessions) ? Math.min(1, appliedPrompts / prompts) : null;
475	  return { usedShare: share, usedBy: share == null ? null : 'prompts', wasted: share == null ? null : Math.round(perPrompt * (1 - share)), wastedWindow: share == null || window == null ? null : Math.round(window * (1 - share)) };
476	}
477	
478	// Wasted is what a part cost in the sessions that did not use it. High waste: 5% or more of what its kind (the file,
479	// the skills, the tools) costs a session; medium: 2%; else low. That is the whole rule (until 2026-10-22 a part used in
480	// half the sessions or more was never flagged, whatever it cost in the rest; dropped, the owner found the two-part rule
481	// hard to read). The saving is that cost, at most: a session that needed the part would go without. Unknown while
482	// there is nothing to say how often it is used.
483	export const WASTE = { high: 0.05, medium: 0.02 };
484	export function wasteLevel(r, kindCost) {
485	  if (r.wasted == null) return { waste: 'unknown', wasteShare: null };
486	  const share = kindCost ? r.wasted / kindCost : 0;
487	  return { waste: share >= WASTE.high ? 'high' : share >= WASTE.medium ? 'medium' : 'low', wasteShare: share };
488	}
489	
490	// A plain label for the table: `used` when sessions acted on it, `rare` when it bore on almost none, `unknown`
491	// while there is too little to say.
492	export function valueOf({ sessions, applied, triggered, judged, bore, followed, violated }) {
493	  if (judged >= RARE.minSessions) {
494	    if (followed + violated > 0 && (followed + violated) / judged >= RARE.share) return 'used';
495	    if (bore / judged < RARE.share) return 'rare';
496	    return 'situational';
497	  }
498	  if (triggered && sessions >= RARE.minSessions) return applied / sessions >= RARE.share ? 'situational' : 'rare';
499	  return 'unknown';
500	}
