1	// LLM backend for distilling, verifying and mining. Providers:
2	//   anthropic  Anthropic SDK (ANTHROPIC_API_KEY)
3	//   claude     `claude -p`, Claude Code's headless mode
4	//   codex      `codex exec`
5	//   cursor     `agent -p` (Cursor's CLI)
6	//   gemini     `gemini -p`
7	//   openai     THINKER_LLM_BASE_URL: any OpenAI-compatible /chat/completions
8	//              endpoint (a corporate gateway, a local server); the token comes
9	//              from the variable THINKER_LLM_API_KEY_ENV names, else
10	//              THINKER_LLM_API_KEY, else OPENAI_API_KEY; THINKER_LLM_MODEL or
11	//              the repository's distillModel/verifyModel name the model
12	//   command    THINKER_LLM_CMD: any shell command that reads the prompt on
13	//              stdin and prints the answer; THINKER_TIER, THINKER_MODEL and
14	//              THINKER_SCHEMA in its environment say what was asked for
15	// Each agent uses the login it already has. THINKER_LLM picks one; otherwise
16	// the first that is available, preferring THINKER_LLM_PREFER (set by the hooks
17	// to the agent that is running). All return a parsed JSON object when a
18	// schema is given.
19	
20	// The model distillation and mining fall back to when neither the call nor the repository's config names
21	// one; the page shows the same default (test/cli-ui-sync.test.js).
22	export const DEFAULT_DISTILL_MODEL = 'sonnet';
23	import { spawn } from 'node:child_process';
24	import os from 'node:os';
25	import fs from 'node:fs';
26	import path from 'node:path';
27	import { logModelUsage, normalizeModelUsage } from './model-usage.js';
28	import { viaSession } from './session-llm.js';
29	const ALIASES = { haiku: 'claude-haiku-5-5', sonnet: 'claude-sonnet-5-5', opus: 'claude-opus-5-5', fable: 'claude-fable-5-1' };
30	export const BINS = { claude: ['claude'], gemini: ['agy', 'gemini'], codex: ['codex'], cursor: ['agent', 'cursor-agent'] };
31	export const FALLBACK_ORDER = ['claude', 'gemini', 'codex', 'cursor'];
32	export const TIERS = ['haiku', 'sonnet', 'opus', 'fable'];
33	
34	export const TIER_MODELS = {
35	  sonnet: {
36	    claude: 'sonnet',
37	    gemini: 'gemini-3.8-flash-high',
38	    codex: 'gpt-6-luna',
39	    cursor: 'sonnet',
40	  },
41	  haiku: {
42	    claude: 'haiku',
43	    gemini: 'gemini-3.8-flash-high',
44	    codex: 'gpt-6-luna',
45	    cursor: 'haiku',
46	  },
47	  opus: {
48	    claude: 'opus',
49	    gemini: 'gemini-3.8-flash-high',
50	    codex: 'gpt-6-luna',
51	    cursor: 'opus',
52	  },
53	};
