55	export function resolveModel(provider, model) {
56	  if (process.env.THINKER_LLM_MODEL) return process.env.THINKER_LLM_MODEL;
57	  const tier = model || 'sonnet';
58	  if (TIER_MODELS[tier] && TIER_MODELS[tier][provider]) return TIER_MODELS[tier][provider];
59	  if (model && !TIERS.includes(model)) return model;
60	  if (provider === 'gemini') return 'gemini-3.8-flash-high';
61	  if (provider === 'codex') return 'gpt-6-luna';
62	  return model || 'sonnet';
63	}
64	
65	// The login side of the user's Claude Code settings: of the env block, the entries that say where
66	// the model is and how to authenticate (a gateway's ANTHROPIC_BASE_URL and ANTHROPIC_AUTH_TOKEN, the
67	// Bedrock, Vertex and Foundry switches and their cloud credentials, proxies and certificates), with
68	// apiKeyHelper and the AWS credential helpers. A call runs with --setting-sources '' so that hooks,
69	// permissions, plugins and skills stay out of it; without this the login configured there was out
70	// too, and every call failed to authenticate. Claude Code reads --settings on top of the sources, so
71	// the login goes back in that way. Model mappings belong to the route too: a gateway may only
72	// serve its deployment names. Telemetry exporters and thinker's per-call limits stay out.
73	const LOGIN_ENV = /^(ANTHROPIC_(BASE_URL|AUTH_TOKEN|API_KEY|CUSTOM_HEADERS|DEFAULT_(SONNET|HAIKU|OPUS|FABLE)_MODEL$|BEDROCK_|VERTEX_|FOUNDRY_)|CLAUDE_CODE_(USE_|SKIP_|CLIENT_)|AWS_|GOOGLE_|GCLOUD_|CLOUD_ML_REGION$|AZURE_|HTTPS?_PROXY$|NO_PROXY$|NODE_EXTRA_CA_CERTS$|SSL_CERT_|NODE_TLS_)/;
74	export function claudeLoginSettings(dir = process.env.CLAUDE_CONFIG_DIR || path.join(os.homedir(), '.claude'), repo) {
75	  const out = {};
76	  const files = [path.join(dir, 'settings.json'), ...(repo ? ['settings.json', 'settings.local.json'].map(n => path.join(repo, '.claude', n)) : [])];
77	  for (const file of files) {
78	    let s; try { s = JSON.parse(fs.readFileSync(file, 'utf8')); } catch { continue; }
79	    if (!s || typeof s !== 'object') continue;
80	    if (s.env && typeof s.env === 'object') {
81	      const env = Object.fromEntries(Object.entries(s.env).filter(([k]) => LOGIN_ENV.test(k)));
82	      if (Object.keys(env).length) out.env = { ...out.env, ...env };
83	    }
84	    for (const k of ['apiKeyHelper', 'awsAuthRefresh', 'awsCredentialExport']) if (s[k] !== undefined) out[k] = s[k];
85	  }
86	  return Object.keys(out).length ? out : null;
87	}
