89	// Hooks run with a short PATH; also look where these tools install themselves. The Codex desktop app
90	// ships its CLI inside ChatGPT.app, off PATH, signed in with the app (they share ~/.codex).
91	export function findBin(names) {
92	  const dirs = [...(process.env.PATH || '').split(path.delimiter), path.join(os.homedir(), '.local', 'bin'), '/opt/homebrew/bin', '/usr/local/bin',
93	    ...(process.platform === 'darwin' ? ['/Applications/ChatGPT.app/Contents/Resources/codex-cli/bin', '/Applications/Codex.app/Contents/Resources'] : [])].filter(Boolean);
94	  for (const n of names) for (const d of dirs) { const f = path.join(d, n); try { fs.accessSync(f, fs.constants.X_OK); return f; } catch {} }
95	  return null;
96	}
97	export function available() {
98	  const out = [];
99	  if (process.env.THINKER_LLM_CMD) out.push('command');
100	  if (process.env.THINKER_LLM_BASE_URL) out.push('openai');
101	  if (process.env.ANTHROPIC_API_KEY && process.env.THINKER_BACKEND !== 'cli') out.push('anthropic');
102	  for (const p of ['claude', 'gemini', 'codex', 'cursor']) if (findBin(BINS[p])) out.push(p);
103	  return out;
104	}
105	
106	let activeFallback = null;
107	
108	export function resetFallback() {
109	  activeFallback = null;
110	}
111	
112	// The provider a model id belongs to, when the id names one; null for a tier name or anything else.
113	export function providerOfModel(model) {
114	  const m = String(model || '');
115	  if (/^(gpt-|o\d|codex)/i.test(m)) return 'codex';
116	  if (/^gemini-/i.test(m)) return 'gemini';
117	  if (/^claude-/i.test(m)) return 'claude';
118	  return null;
119	}
120	
121	export function getFallbackOrder() {
122	  const want = process.env.THINKER_LLM;
123	  if (want) {
124	    // session: the person's agent session answers (session-llm.js); only ever pinned, never detected
125	    if (want === 'anthropic' || want === 'command' || want === 'openai' || want === 'session' || BINS[want]) return [want];
126	    throw new Error(`unknown THINKER_LLM: ${want}`);
127	  }
128	  const have = available();
129	  const list = [];
130	  const prefer = process.env.THINKER_LLM_PREFER;
131	  if (activeFallback && have.includes(activeFallback)) {
132	    list.push(activeFallback);
133	  } else if (prefer && have.includes(prefer) && !have.includes('command') && !have.includes('openai') && !have.includes('anthropic')) {
134	    list.push(prefer);
135	  }
136	  for (const p of ['command', 'openai', 'anthropic', 'claude', 'gemini', 'codex', 'cursor']) {
137	    if (have.includes(p) && !list.includes(p)) list.push(p);
138	  }
139	  return list;
140	}
141	
142	export function provider() {
143	  return getFallbackOrder()[0] || null;
144	}
