146	async function executeProvider(p, opts) {
147	  let reported = false;
148	  const resolved = resolveModel(p === 'anthropic' ? 'claude' : p, opts.model);
149	  // the session's own model answers a session call, whichever it is: no tier picks it
150	  const model = p === 'session' ? 'session' : ['claude', 'anthropic'].includes(p) ? ALIASES[resolved] || resolved : resolved;
151	  let response = { provider: p, model, usage: null, cost: null };
152	  // Capture counters before parsing the model's JSON, so unusable answers still count.
153	  const o = { ...opts,
154	    onUsage: fields => { response = { ...response, ...fields }; reported = true; },
155	    onRetry: () => {
156	      if (opts.accounting) logModelUsage(opts.accounting.store, opts.accounting, { ...response, failed: true });
157	      response = { provider: p, model, usage: null, cost: null }; reported = false;
158	    },
159	  };
160	  try {
161	    const res = await (p === 'anthropic' ? viaSdk(o) : p === 'openai' ? viaOpenai(o) : p === 'claude' ? viaCli(o) : p === 'session' ? viaSession(o) : viaOther(p, o));
162	    if (!reported) response = { ...response, ...res };
163	    if (opts.accounting) logModelUsage(opts.accounting.store, opts.accounting, response);
164	    // every answer carries its normalized counters, so a caller can say what the run used in tokens
165	    return { ...res, model: response.model, tokens: normalizeModelUsage(p, response.usage) };
166	  } catch (err) {
167	    if (opts.accounting) logModelUsage(opts.accounting.store, opts.accounting, { ...response, failed: true });
168	    throw err;
169	  }
170	}
171	
172	export async function complete(opts) {
173	  const o = { model: 'sonnet', maxTokens: 8000, timeoutMs: 300_000, ...opts };
174	  // a model id that names its provider is answered by that provider or not at all: falling back hands
175	  // the id to a CLI that does not have it, or answers with another model under its name (a benchmark
176	  // judge named gpt-6-luna was mostly graded through the Claude CLI, 2026-10-16). Tier names (sonnet,
177	  // haiku, …) keep the fallback order.
178	  const pinned = process.env.THINKER_LLM ? null : providerOfModel(o.model);
179	  const serves = p => p === pinned || p === 'command' || (pinned === 'claude' && p === 'anthropic') || (pinned === 'codex' && p === 'openai');
