211	  function postProcess(obj) {
212	    if (!obj || typeof obj !== 'object') return null;
213	    if (Array.isArray(obj) && schema?.properties) {
214	      const keys = Object.keys(schema.properties);
215	      if (keys.length === 1 && schema.properties[keys[0]]?.type === 'array') {
216	        return { [keys[0]]: obj };
217	      }
218	      if (schema.properties.notes?.type === 'array') {
