654	  // usage limits: wait and retry instead of failing the caller, unless other fallbacks exist
655	  const hasFallback = getFallbackOrder().length > 1;
656	  const maxAttempts = hasFallback ? 1 : 18;
657	  for (let attempt = 0; ; attempt++) {
658	    try { return await viaCliOnce(opts); }
659	    catch (e) {
660	      // the model tried to call a tool although none is offered (seen with long code prompts): try again at once, twice
661	      if (/"stop_reason":"tool_use"/.test(String(e.message)) && attempt < 2) { opts.onRetry(); continue; }
662	      // A selected harness stays selected. Retry short-lived process/API failures twice before
663	      // handing the failure to the caller (or to the existing provider fallback, when unpinned).
664	      if (e.retryable && attempt < 2) {
665	        opts.onRetry();
666	        await new Promise(r => setTimeout(r, 1000 * 2 ** attempt));
667	        continue;
668	      }
669	      if (!LIMIT_RE.test(String(e.message)) || attempt >= maxAttempts || process.env.THINKER_NO_LIMIT_WAIT === '1') throw e;
670	      opts.onRetry();
671	      await new Promise(r => setTimeout(r, 10 * 60_000));
672	    }
673	  }
674	}
