676	const CLI_SYSTEM = 'Answer the request directly. No tools are available.';
677	
678	// The CLI counts thinking against CLAUDE_CODE_MAX_OUTPUT_TOKENS, and no switch turns thinking off any
679	// more: on claude 2.1.296 with Haiku 5.5, MAX_THINKING_TOKENS=0, CLAUDE_CODE_DISABLE_THINKING=1,
680	// CLAUDE_CODE_DISABLE_ADAPTIVE_THINKING=1 and CLAUDE_CODE_EFFORT_LEVEL=low each left 6,600-9,300 thinking
681	// tokens on an eight-note phrasing call whose answer is under 3,000. A caller's maxTokens is the room its
682	// answer needs, so the cap handed to the CLI adds this much for thinking. A cap is a ceiling, not spend;
683	// a cap that thinking exhausts is the expensive case: the CLI retries the request up to four times,
684	// burning the whole cap in thinking each time, then exits 1 with nothing saved (a third of the week's
685	// phrasing and design-document calls on this machine, ~/.thinker/log.jsonl, 2026-10-13).
686	export const THINKING_HEADROOM = 16_000;
687	export const cliOutputCap = maxTokens => (maxTokens || 0) + THINKING_HEADROOM;
688	
689	// claude -p exits 1 with nothing on stderr when the answer (its thinking included) reaches the output
690	// cap. Current versions say so in api_error and result (stop_reason stays "stop_sequence", iterations
691	// is empty); older ones only carried the counters. '' when that is not it. `cap` is the cap the CLI
692	// enforced (cliOutputCap), the number the message names.
693	export function overCap(stdout, cap) {
694	  try {
695	    const j = JSON.parse(stdout);
696	    const last = (j.usage?.iterations || []).at(-1);
697	    const hit = j.stop_reason === 'max_tokens' || j.api_error === 'max_output_tokens'
698	      || /exceeded the \d+ output token maximum/.test(String(j.result || ''))
699	      || (cap && last?.output_tokens >= cap);
700	    return hit ? `the answer ran past the ${cap}-token output cap (ask for less in one call)` : '';
701	  } catch { return ''; }
702	}
703	
704	function claudeFailure(stdout, stderr, code, cap) {
705	  let j; try { j = JSON.parse(stdout); } catch {}
706	  const over = overCap(stdout, cap);
707	  const detail = [j?.result, ...(Array.isArray(j?.errors) ? j.errors : []), j?.error?.message || j?.error]
708	    .filter(v => typeof v === 'string' && v.trim()).join('; ');
709	  // Put the reason before metadata: setup only has room for the first 120 characters.
710	  const reason = over || detail || stderr.trim() || j?.subtype || stdout.trim() || 'no error details';
711	  const error = new Error(`claude -p exited ${code}: ${reason.slice(0, 500)}`);
712	  if (over) error.code = 'MODEL_OUTPUT_LIMIT';
713	  error.retryable = !over && !LIMIT_RE.test(reason) && (
714	    j?.stop_reason === 'tool_use'
715	    || /overloaded|temporarily unavailable|internal server error|\b50[234]\b|ECONNRESET|ETIMEDOUT|fetch failed|socket hang up/i.test(reason)
716	    || (!detail && !stderr.trim() && (!j?.subtype || j.subtype === 'error_during_execution'))
717	  );
718	  return error;
719	}
