721	async function viaCliOnce({ system, prompt, model, schema, maxTokens, thinkingTokens, structuredRetries, timeoutMs, cache = true, onUsage, accounting }) {
722	  // Run in an empty temp cwd so no project CLAUDE.md / MCP servers leak in.
723	  const cwd = fs.mkdtempSync(path.join(os.tmpdir(), 'thinker-llm-'));
724	  const login = claudeLoginSettings(undefined, accounting?.store?.repo || process.cwd());
725	  const tier = resolveModel('claude', model);
726	  const mapping = `ANTHROPIC_DEFAULT_${tier.toUpperCase()}_MODEL`;
727	  const resolved = ALIASES[tier] ? login?.env?.[mapping] || process.env[mapping] || ALIASES[tier] : tier;
728	  const args = ['-p', '--model', resolved, '--output-format', 'json', '--no-session-persistence',
729	    '--tools', '', '--strict-mcp-config', '--mcp-config', '{"mcpServers":{}}',
730	    // Replace Claude Code's own system prompt rather than append to it: appended, every call sent ~7k
731	    // tokens of agent instructions, written to the one-hour prompt cache (twice the input price) and
732	    // never read again. No settings or skills either: neither is used, both add to the prompt.
733	    '--system-prompt', system || CLI_SYSTEM, '--setting-sources', '', '--disable-slash-commands'];
734	  if (login) args.push('--settings', JSON.stringify(login));
735	  if (schema) args.push('--json-schema', JSON.stringify(schema));
736	  try {
737	    const { stdout, stderr, code } = await new Promise((resolve, reject) => {
738	      const p = spawn(findBin(BINS.claude) || 'claude', args, { cwd, env: { ...process.env, THINKER_IN_LLM: '1', CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC: '1', CLAUDE_CODE_MAX_OUTPUT_TOKENS: String(cliOutputCap(maxTokens)), ...(thinkingTokens === undefined ? {} : { MAX_THINKING_TOKENS: String(thinkingTokens) }), ...(structuredRetries === undefined ? {} : { MAX_STRUCTURED_OUTPUT_RETRIES: String(structuredRetries) }), ...(cache ? {} : { DISABLE_PROMPT_CACHING: '1' }) } });
739	      let o = '', e = '';
740	      const timer = setTimeout(() => { p.kill('SIGKILL'); reject(Object.assign(new Error('claude -p timed out'), { retryable: true })); }, timeoutMs);
741	      p.stdout.on('data', d => o += d); p.stderr.on('data', d => e += d);
742	      p.on('error', err => { clearTimeout(timer); reject(err); });
743	      p.on('close', code => { clearTimeout(timer); resolve({ stdout: o, stderr: e, code }); });
744	      p.stdin.end(prompt);
745	    });
746	    let j;
747	    try { j = JSON.parse(stdout); }
748	    catch (e) { if (code !== 0) throw claudeFailure(stdout, stderr, code, cliOutputCap(maxTokens)); throw e; }
749	    onUsage({ usage: j.usage, cost: j.total_cost_usd, model: j.model || ALIASES[resolved] || resolved });
750	    if (code !== 0 || j.is_error || (LIMIT_RE.test(String(j.result || '').slice(0, 200)) && (j.num_turns || 0) <= 1)) throw claudeFailure(stdout, stderr, code, cliOutputCap(maxTokens));
751	    let json = j.structured_output ?? null;
752	    if (schema && json == null) { try { json = JSON.parse(j.result); } catch { throw new Error('no structured output: ' + String(j.result).slice(0, 300)); } }
753	    return { text: j.result, json, usage: j.usage, cost: j.total_cost_usd, provider: 'claude' };
754	  } finally { try { fs.rmSync(cwd, { recursive: true, force: true }); } catch {} }
755	}
