208	// --- what switching off saved -----------------------------------------------------------------------
209	// a session started at `start`, with `calls` model calls, loading what loadedLines loads minus `without`
210	function laterSession(dir, id, start, { calls = 4, without = [] } = {}) {
211	  const drop = n => without.some(w => n.startsWith(w));
212	  const lines = loadedLines().map(j => {
213	    const a = j.attachment;
214	    if (a.type === 'deferred_tools_delta') return { ...j, timestamp: start, attachment: { ...a, addedNames: a.addedNames.filter(n => !drop(n)) } };
215	    if (a.type === 'mcp_instructions_delta') { const keep = a.addedNames.map((n, i) => [n, a.addedBlocks[i]]).filter(([n]) => !without.some(w => w === `mcp__${n}__`)); return { ...j, attachment: { ...a, addedNames: keep.map(k => k[0]), addedBlocks: keep.map(k => k[1]) } }; }
216	    if (a.type === 'skill_listing') { const names = a.names.filter(n => !drop(`skill:${n}`)); return { ...j, attachment: { ...a, names, content: a.content.split(/\n(?=- \S)/).filter(e => names.some(n => e.startsWith(`- ${n}`))).join('\n') } }; }
217	    return j;
218	  });
219	  for (let i = 0; i < calls; i++) lines.push({ type: 'assistant', message: { id: `m${id}${i}`, usage: { input_tokens: 10 }, content: [{ type: 'text', text: 'ok' }] } });
220	  fs.writeFileSync(path.join(dir, `${id}.jsonl`), lines.map(j => JSON.stringify(j)).join('\n') + '\n');
221	  return { client: 'claude', file: path.join(dir, `${id}.jsonl`), session: id, mtime: Date.parse(start) };
222	}
