143	      L.set(t, { op: 'session', session: `s${i}`, model: t === 4 ? 'n' : 'm', toolCalls: 10 * t + (i % 3 === 0 && t >= 3 ? 10 : 0), inputTokens: cost, turns: 5 * t });
144	      T.set(t, { served: holdout ? 0 : 2, withheld: holdout ? 2 : 0, holdout, corrected: holdout && i === 0 });
145	    }
146	    lines.set(k, L); turns.set(k, T);
147	  }
148	  // a turn with nothing to serve either way; a turn whose stop line is missing; a turn whose previous line is missing
149	  turns.get('o|s1').set(5, { served: 0, withheld: 0, holdout: true });
150	  turns.get('o|s2').set(5, { served: 1, withheld: 0, holdout: false });
151	  turns.get('o|s4').set(6, { served: 1, withheld: 0, holdout: false }); lines.get('o|s4').set(6, { model: 'm', toolCalls: 99, inputTokens: 9e9, turns: 1 });
