155	  assert.equal(h.served.perPrompt.inputTokens, 1_000_000); assert.equal(h.heldOut.perPrompt.inputTokens, 2_000_000);
156	  assert.equal(h.served.perPrompt.toolCalls, 10, 'the turn\'s own tool calls, not the session\'s');
157	  assert.equal(h.heldOut.perPrompt.toolCalls, 20);
158	  assert.equal(h.deltaPct.inputTokens, -50); assert.equal(h.deltaPct.toolCalls, -50);
159	  assert.equal(h.saved.inputTokens, 44_000_000, '(held-out − served) per prompt × served prompts');
160	  assert.equal(h.heldOut.corrected, 1); assert.equal(h.served.corrected, 0);
161	  assert.deepEqual(Object.keys(h.byModel).sort(), ['m', 'n']); assert.equal(h.byModel.n.served.prompts, 12); assert.equal(h.byModel.n.heldOut.prompts, 0);
