1	// `thinker ui`: a local page for the person, on this machine only. Three views: Save, where the agents' context goes in
2	// a repository and what each part is worth, with the cuts (context-view.js, as `thinker context`); Report, what a
3	// session costs here week by week, by part of the context and by model, in tokens or at list prices, with the
4	// decisions taken on Save and the cache's numbers under it (report.js, as `thinker report`); and Recent activity, every
5	// decision taken with what came of it and what still needs the person (context-suggest.js:changeHistory, as `thinker
6	// context --history`): a compression running in the background or failed, a pull request waiting to be merged. The
7	// Cache view (the usage cards, the repositories, the notes and the behaviors) was replaced by Report on 2026-10-22, at
8	// the owner's decision; the notes and behaviors are the CLI's (`thinker list`, `show`, `archive`, `system`).
9	//
10	// The page is machine-wide: it needs no repository, and a repository is named by its id (as the log
11	// names it) so the page cannot be pointed at a path.
12	//
13	// It listens on 127.0.0.1 alone. The Host header must name this server (a DNS rebinding names another),
14	// and an API call that a browser marks as coming from another site (its Origin header, or
15	// Sec-Fetch-Site: cross-site) is refused, so another page in the browser can neither read the report nor
16	// change a setting. Until 2026-10-22 every call also carried a key minted for the run, in the page's
17	// address; the owner dropped it: a copied address without it was a broken page, and the two checks above
18	// keep the same pages out.
19	import { harnessView, harnessSavings, harnessOn, undoHarness, switchOffNow, setHarnessSettings } from '../harness.js';
20	import { contextView, mergeViews, switchSources, setOutputCompression } from '../context-view.js';
21	import { snapshotView, lastSnapshot, refreshing, dropSnapshots, REFRESH_MS } from '../context-snapshot.js';
22	import { approveChanges, dismissChanges, startSectionJob, retryJob, revertDecision, pickChanges, allChanges, changeHistory, refreshPrStates, offeredPicks, VIA } from '../context-suggest.js';
23	import { mergeReports, reportActions, withEffects, mergePromptAverages, REPORT_WEEKS } from '../report.js';
24	import { reportSnapshot, refreshing as reportRefreshing, historyEffects, promptAverageHere, keptRows } from '../report-snapshot.js';
25	import { prAvailable } from '../instruction-pr.js';
26	import { describePart } from '../part-describe.js';
27	import { attachExplains, readExplains, missingExplains } from '../part-explain.js';
28	import { uiScans, scanStatus } from './scans.js';
29	import http from 'node:http';
30	import fs from 'node:fs';
31	import path from 'node:path';
32	import { spawn } from 'node:child_process';
33	import { fileURLToPath } from 'node:url';
34	import { Store, repoId, isGitCheckout } from '../store.js';
35	import { discoverRepos, displayName } from '../machine.js';
36	import { thinkerHome } from '../update.js';
37	import { isDisabledRepo } from '../repo-switch.js';
