39	const HERE = path.dirname(fileURLToPath(import.meta.url));
40	export const DEFAULT_PORT = 4848;
41	
42	// The repositories with a cache on this machine: this one, and every checkout the agents' transcripts
43	// or the machine's log name that has a .thinker folder. A repository with several checkouts (clones,
44	// worktrees) is read from the one holding the most notes, this one when they tie. `checkouts`: the ones
45	// found before (keptCheckouts), instead of looking again.
46	export function machineRepos(store, { home, checkouts } = {}) {
47	  const here = isGitCheckout(store.repo) && store.exists() ? store.repo : null;
48	  const byOrigin = new Map();
49	  const add = c => { const o = repoId(c); if (!byOrigin.has(o)) byOrigin.set(o, new Set()); byOrigin.get(o).add(c); };
50	  if (here) add(here);
51	  for (const c of checkouts || discoverCheckouts(store, { home })) if (fs.existsSync(path.join(c, '.thinker'))) add(c);
52	  const count = c => { try { return new Store(c, { readonly: true }).count(); } catch { return -1; } };
53	  const out = [];
54	  for (const [id, checkouts] of byOrigin) {
55	    const scored = [...checkouts].map(c => [c, count(c)]).filter(([, n]) => n >= 0).sort((a, b) => b[1] - a[1] || (b[0] === here) - (a[0] === here));
56	    if (!scored.length) continue;
57	    const checkout = scored[0][0];
58	    out.push({ id, name: displayName(id, checkout), checkout, current: checkout === here, disabled: isDisabledRepo(checkout) });
59	  }
60	  return out.sort((a, b) => b.current - a.current || a.name.localeCompare(b.name));
61	}
