63	// Finding the checkouts reads every agent's project folders and the machine's log: two to four seconds on this
64	// machine (6,000 Claude Code project folders, most of them benchmark runs), before the page shows anything. So
65	// they are kept under thinker's home (state/machine-checkouts.json) and the page reads them, starting `thinker ui
66	// --refresh` in the background when they are older than REPOS_REFRESH_MS; which checkout stands for a repository,
67	// and whether it is this one, is worked out live from them.
68	export const REPOS_REFRESH_MS = 10 * 60_000;
69	const checkoutsFile = home => path.join(home, 'state', 'machine-checkouts.json');
70	export function discoverCheckouts(store, { home } = {}) {
71	  let found = []; try { found = discoverRepos(store, { home }); } catch {}
72	  return found.flatMap(r => r.checkouts).filter(c => fs.existsSync(path.join(c, '.thinker')));
73	}
74	// `transcriptsHome`: where the agents' transcripts were read (tests name one); a list read elsewhere is not used
75	export function keptCheckouts({ home = thinkerHome(), transcriptsHome } = {}) {
76	  try { const s = JSON.parse(fs.readFileSync(checkoutsFile(home), 'utf8')); return s.transcripts === (transcriptsHome || null) && Array.isArray(s.checkouts) ? s : null; } catch { return null; }
77	}
78	export function refreshCheckouts(store, { home = thinkerHome(), transcriptsHome, now = Date.now() } = {}) {
79	  const checkouts = discoverCheckouts(store, { home: transcriptsHome }), f = checkoutsFile(home), tmp = `${f}.${process.pid}.tmp`;
80	  try { fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(tmp, JSON.stringify({ at: now, transcripts: transcriptsHome || null, checkouts })); fs.renameSync(tmp, f); }
81	  catch { try { fs.rmSync(tmp, { force: true }); } catch {} }
82	  return checkouts;
83	}
