85	// The background refreshes the page starts (a Context report, the Report's figures: `thinker context --refresh`,
86	// `thinker report --refresh`) run one at a time, each asked for once while it waits: over a dozen repositories the
87	// page started a dozen node processes at once, each reading the machine's log and its transcripts, and the machine
88	// crawled while they ran. `start` spawns the process and returns it, or nothing to skip.
89	export function serialSpawner() {
90	  const queue = [], waiting = new Set(); let busy = false;
91	  const next = () => {
92	    if (busy || !queue.length) return;
93	    const { key, start } = queue.shift(); waiting.delete(key);
94	    let p = null; try { p = start(); } catch {}
95	    if (!p) return next();
96	    busy = true;
97	    const done = () => { if (!busy) return; busy = false; next(); };
98	    p.on('exit', done); p.on('error', done);
99	  };
100	  return (key, start) => { if (waiting.has(key)) return false; waiting.add(key); queue.push({ key, start }); next(); return true; };
101	}
