109	export function createUiServer(store, { home = thinkerHome(), transcriptsHome, cliPath = path.join(HERE, '..', 'cli.js'), refreshFn, refreshReportFn, refreshReposFn, spawnFn = spawn } = {}) {
110	  refreshReposFn ||= () => { try { const p = spawn(process.execPath, [cliPath, 'ui', '--refresh'], { cwd: store.repo, stdio: 'ignore', detached: true }); p.on('error', () => {}); p.unref(); } catch {} };
111	  const background = serialSpawner();
112	  const child = (args, cwd) => { const p = spawn(process.execPath, [cliPath, ...args], { cwd, stdio: 'ignore', detached: true }); p.on('error', () => {}); p.unref(); return p; };
113	  // an old Context report is made again by `thinker context --refresh` in the checkout, in the background
114	  refreshFn ||= checkout => background(`context:${checkout}`, () => child(['context', '--refresh', '--quiet', '--repo', checkout], checkout));
115	  // an old Report by `thinker report --refresh`: one repository's, or every repository's in one run (null)
116	  refreshReportFn ||= checkout => checkout ? background(`report:${checkout}`, () => child(['report', '--refresh', '--quiet', '--repo', checkout], checkout)) : background('report:all', () => child(['report', '--refresh', '--all', '--quiet'], store.repo));
117	  const scans = uiScans();
118	  let discovering;
119	  const page = fs.readFileSync(path.join(HERE, 'page.html'), 'utf8');
120	  let port = 0, known = null, lastRequest = Date.now();
121	  // the checkouts found before, looked for again in the background when old (once a while per process)
122	  let refreshedAt = 0;
123	  const listRepos = () => {
124	    const kept = keptCheckouts({ home, transcriptsHome });
125	    if (!kept) return machineRepos(store, { home: transcriptsHome, checkouts: refreshCheckouts(store, { home, transcriptsHome }) });
126	    if (Date.now() - kept.at > REPOS_REFRESH_MS && Date.now() - refreshedAt > REPOS_REFRESH_MS) { refreshedAt = Date.now(); refreshReposFn(); }
127	    return machineRepos(store, { home: transcriptsHome, checkouts: kept.checkouts });
128	  };
