399	// The definitions a file holds: [{name, parent, kind, line, end}], by the parser when loaded (it
400	// reads the working tree, so it is exact), else from the graph, else by regex.
401	export function outline(repo, file, { limit = 80 } = {}) {
402	  const abs = repoFile(repo, file); if (!abs) return null;
403	  const indexed = outlineFile(repo, file, { limit });  // the symbol table, when this checkout keeps one
404	  if (indexed) return indexed;
405	  let text; try { text = fs.readFileSync(abs, 'utf8'); } catch { return null; }
406	  if (astReady(file)) { const d = outlineText(text, file, { limit }); if (d) return d; }
407	  return outlineText(text, file, { limit });
408	}
