410	// The same over a text that is not (or not yet) in the working tree: the parser when loaded for
411	// the file's language, else the regex. `end` (inclusive, 1-based) is only known from the parser.
412	export function outlineText(text, file, { limit = 80 } = {}) {
413	  if (astReady(file)) { const d = definitions(text, file); if (d) return d.slice(0, limit).map(x => ({ name: x.name, parent: x.parent, kind: x.kind, line: x.start + 1, end: x.end })); }
414	  const out = []; const lines = text.split('\n');
415	  const re = new RegExp(`^(\\s*)(?:export\\s+(?:default\\s+)?)?(?:pub(?:\\([^)]*\\))?\\s+)?(?:async\\s+)?(?:(${DEF_WORDS})\\s+([A-Za-z_]\\w*)|(?:const|let|var)\\s+([A-Za-z_]\\w*)\\s*[=:]\\s*(?:async\\s*)?(?:\\([^)]*\\)\\s*=>|function\\b|class\\b)|func\\s*\\([^)]*\\)\\s*([A-Za-z_]\\w*)\\s*\\()`);
416	  const parents = []; // [{name, indent}] for Python-style nesting
417	  for (let i = 0; i < lines.length && out.length < limit; i++) {
418	    const m = re.exec(lines[i]); if (!m) continue;
419	    const indent = m[1].length; const name = m[3] || m[4] || m[5]; let kind = NORM_KIND[m[2]] || m[2] || (m[5] ? 'method' : 'const');
420	    while (parents.length && parents[parents.length - 1].indent >= indent) parents.pop();
421	    const parent = parents.length ? parents[parents.length - 1].name : null;
422	    if (kind === 'function' && parent) kind = 'method';
423	    out.push({ name, parent, kind, line: i + 1 });
424	    if (/^(class|struct|impl|trait|interface|module|enum)$/.test(kind)) parents.push({ name, indent });
425	  }
426	  return out;
427	}
