1	import { verificationChanges } from './freshness.js';
2	// Skills as cached knowledge. A skill is a file (SKILL.md) an agent pulls into its context by name;
3	// its instructions rest on code that moves, so it decays like any note. Each skill file in the
4	// checkout gets a `skill` note: a short card (what the skill is for, when to invoke it, what it
5	// prescribes) whose deps are the file itself and the code the file talks about. Staleness then
6	// comes for free (ops.js:refresh), and a stale card is audited against the current code
7	// (auditSkill). A skill found out of date is `broken`: its issues are recorded on the note, it is
8	// not served, and it is not audited again until the file changes (a person updated it) or a person
9	// reviews it (reviewSkill). Nothing here edits a skill file.
10	//
11	// Where a skill is strong or weak comes from the sessions: an invoked skill (transcripts.js records
12	// the Skill call and its directory) is assessed by the distillation like an injected note, and a
13	// contradiction recorded there marks the skill broken too (ops.js:attest). Among skills that do the
14	// same thing (dedupeSkills), the one with the best evidence is served and the others are archived as
15	// its duplicates; a person can pin one (`skills.prefer` in the config). How-to notes stay what they
16	// are: the cache's own, automatically built skills.
17	import fs from 'node:fs';
18	import path from 'node:path';
19	import { createHash } from 'node:crypto';
20	import { execFileSync } from 'node:child_process';
21	import { complete, DEFAULT_DISTILL_MODEL } from './llm.js';
22	import { tokensOf } from './model-usage.js';
23	import { createNote, extractDeps, resolveDeps, noteUnreported, gitDiffFor } from './ops.js';
24	import { tokenize } from './rank.js';
25	import { gitHead } from './store.js';
26	import { symbolText, hashDep, repoFile } from './deps.js';
27	
28	// Where the agents look for a repository's skills: Claude Code, the agent-skills convention (Codex and
29	// others), Cursor, Copilot, and a plain skills/ directory. Only directories holding a SKILL.md count.
30	export const SKILL_ROOTS = ['.claude/skills', '.agents/skills', '.codex/skills', '.cursor/skills', '.github/skills', 'skills'];
31	export const CARD_CHARS = 20000;   // of the skill file shown to the card writer
32	export const AUDIT_CHARS = 16000;  // of the skill file shown to the audit
33	export const EVIDENCE_CHARS = 3500; // of the skill file shown to a session's assessment
34	export const MAX_CODE_DEPS = 10;    // code deps per card, symbol pointers first, documents last
