39	// name and description from the YAML front matter; the body after it
40	export function parseSkill(text) {
41	  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(text);
42	  const meta = {};
43	  if (m) {
44	    let key = null;
45	    for (const line of m[1].split(/\r?\n/)) {
46	      const kv = /^([A-Za-z_][\w-]*):\s*(.*)$/.exec(line);
47	      if (kv) { key = kv[1]; meta[key] = kv[2].replace(/^(["'])(.*)\1$/, '$2').replace(/^[>|]-?$/, '').trim(); }
48	      else if (key && /^\s+\S/.test(line)) meta[key] = (meta[key] + ' ' + line.trim()).trim();
49	    }
50	  }
51	  return { name: meta.name || '', description: meta.description || '', body: m ? text.slice(m[0].length) : text, meta };
52	}
