54	// The skill files of a checkout: { name, file, dir, root, description }.
55	export function findSkills(repo, { roots = SKILL_ROOTS } = {}) {
56	  const out = [];
57	  for (const root of roots) {
58	    const abs = repoFile(repo, root);
59	    if (!abs) continue;
60	    let entries = []; try { entries = fs.readdirSync(abs, { withFileTypes: true }); } catch { continue; }
61	    for (const e of entries) {
62	      if (!e.isDirectory() && !e.isSymbolicLink()) continue;
63	      const file = path.posix.join(root, e.name, 'SKILL.md');
64	      const fileAbs = repoFile(repo, file);
65	      if (!fileAbs || !fs.existsSync(fileAbs)) continue;
66	      let text; try { text = fs.readFileSync(fileAbs, 'utf8'); } catch { continue; }
67	      const p = parseSkill(text);
68	      out.push({ name: p.name || e.name, dir: e.name, file, root, description: p.description, text, hash: hashOf(text) });
69	    }
70	  }
71	  return out.sort((a, b) => a.file.localeCompare(b.file));
72	}
