80	// The code a skill names: path:Symbol pointers and paths of any kind in backticks or prose.
81	export function skillDepsFromText(repo, text) {
82	  const deps = extractDeps(repo, text, []);
83	  const seen = new Set(deps.map(d => d.path));
84	  for (const m of text.matchAll(/(?:^|[\s(`'"*])((?:[\w.-]+\/)+[\w.-]+\.[A-Za-z0-9]{1,8})(?=[\s)`'",.:;]|$)/g)) {
85	    const p = m[1].replace(/^\.\//, '');
86	    if (seen.has(p) || /^https?:/.test(p) || p.includes('..')) continue;
87	    const abs = repoFile(repo, p);
88	    if (abs && fs.existsSync(abs) && fs.statSync(abs).isFile()) { seen.add(p); deps.push({ path: p }); }
