106	// One model call: the card of a skill file, as createNote input (deps resolved to the checkout).
107	export async function skillCard(store, skill, { model, completeFn = complete, phase = 'maintenance' } = {}) {
108	  const repo = store.repo;
109	  const extracted = skillDepsFromText(repo, skill.text);
110	  const files = [...new Set(extracted.map(d => d.path))];
111	  const prompt = `SKILL ${skill.name} (${skill.file})\nDescription: ${skill.description || '(none)'}\n\nRESOLVED FILES THE SKILL NAMES (the only paths deps may use${files.length ? '' : ': none; deps may then be empty'}):\n${files.map(f => `- ${f}`).join('\n') || '(none)'}\n\nSKILL FILE:\n${skill.text.slice(0, CARD_CHARS)}`;
112	  const res = await completeFn({ system: CARD_SYSTEM, prompt, model, schema: CARD_SCHEMA, maxTokens: 3000, thinkingTokens: 0, structuredRetries: 1, accounting: { store, purpose: 'skill-card', phase } });
113	  const j = res.json || {};
114	  const allowed = new Set(files);
115	  // the model's choice of files is the dep list (it was told to leave out passing mentions); every path
116	  // the skill names is the fallback when it chose none. Capped: a card resting on twenty files is stale
117	  // every week and audited for nothing, and a whole-file dep on a document is the worst of them.
118	  const chosen = (Array.isArray(j.deps) ? j.deps : []).filter(d => d && allowed.has(String(d.path).replace(/^\.\//, ''))).map(d => ({ path: String(d.path).replace(/^\.\//, ''), symbol: d.symbol ? String(d.symbol) : undefined }));
