121	  const body = String(j.body || '').trim() || `${skill.description || skill.name}\nInvoke the skill \`${skill.name}\` (${skill.file}) for the full instructions.`;
122	  return {
123	    input: { title: `Skill: ${skill.name}`, kind: 'skill', skill: { name: skill.name, file: skill.file, root: skill.root, description: String(skill.description || '').slice(0, 500) }, body, applies: String(j.applies || skill.description || '').trim() || undefined,
124	      answers: [...new Set([...(Array.isArray(j.answers) ? j.answers : []).map(String), skill.description].filter(Boolean))].slice(0, 6),
125	      tags: ['skill', ...(Array.isArray(j.tags) ? j.tags.map(String) : [])].slice(0, 8), deps, confidence: 0.8 },
126	    tokens: tokensOf(res), cost: res.cost,
127	  };
128	}
