130	// Read the skill files that are new or changed since their card was written, one model call each;
131	// retire the cards of removed files; then settle duplicates. A changed file clears `broken`: the
132	// person updated the skill, and the card goes back into serving and audit.
133	export async function scanSkills(store, { model, limit = 3, again = false, dry = false, completeFn = complete, phase = 'maintenance', conc = 3, onSkill } = {}) {
134	  const repo = store.repo, found = findSkills(repo), notes = skillNotes(store);
135	  model = model || store.config().distillModel || DEFAULT_DISTILL_MODEL;
136	  const res = { found: found.length, skills: [], read: 0, saved: [], updated: [], removed: [], aliases: [], failed: 0, lastError: null, tokens: 0, remaining: 0, duplicates: [] };
137	  const pending = [];
138	  // the same file under two roots (a symlink, or a copy kept for a second agent) is one skill: the
139	  // first root gets the card, the other is an alias and costs nothing
140	  const byHash = new Map();
141	  for (const s of found) { if (byHash.has(s.hash)) res.aliases.push({ file: s.file, of: byHash.get(s.hash).file }); else byHash.set(s.hash, s); }
