143	  for (const s of found) {
144	    if (aliased.has(s.file)) continue;
145	    const n = noteFor(notes, s) || movedNoteFor(notes, s, found);
146	    if (n && n.status !== 'invalid' && n.source?.hash === s.hash && n.skill?.file === s.file && !again) continue;
147	    pending.push({ skill: s, note: n });
148	  }
149	  // a card whose file is gone is retired, free
150	  const files = new Set(found.filter(s => !aliased.has(s.file)).map(s => s.file));
151	  for (const n of notes) {
152	    if (n.status === 'invalid' || files.has(n.skill?.file) || pending.some(p => p.note?.id === n.id)) continue;
153	    const copyOf = res.aliases.find(a => a.file === n.skill?.file)?.of;
154	    res.removed.push({ id: n.id, title: n.title, file: n.skill?.file, copyOf });
155	    if (!dry) { store.put({ ...n, status: 'invalid', invalidReason: copyOf ? `a copy of ${copyOf}, which has the card` : 'skill file removed', verified: new Date().toISOString() }); store.log({ op: 'skill', id: n.id, action: 'removed', file: n.skill?.file, copyOf }); }
156	  }
157	  const batch = pending.slice(0, limit);
158	  res.skills = batch.map(p => p.skill.file); res.remaining = pending.length - batch.length;
159	  if (dry) return res;
160	  const readOne = async ({ skill, note }) => {
161	    onSkill?.(skill.file);
162	    let card;
163	    try { card = await skillCard(store, skill, { model, completeFn, phase }); res.tokens += card.tokens || 0; }
164	    catch (e) { res.failed++; res.lastError = e; return; }
165	    const source = { type: 'skill', ref: skill.file, hash: skill.hash };
166	    const now = new Date().toISOString();
167	    if (note) {
168	      const r = createNote(store, { ...card.input, id: note.id }, { source, reuseId: true });
169	      if (r.error) { res.failed++; res.lastError = new Error(r.error); store.put(note); return; }
170	      const next = { ...r.note, uses: note.uses || 0, created: note.created || r.note.created, attest: note.attest, outcomes: note.outcomes, servedIn: note.servedIn, lastUsed: note.lastUsed,
171	        history: [...(note.history || []), { at: now, reason: note.broken ? 'skill file changed; the issues recorded are left to the next audit' : 'skill file changed', prevBody: note.body, ...(note.broken ? { broken: note.broken } : {}) }].slice(-5) };
172	      delete next.broken; delete next.archived; delete next.invalidReason;
173	      store.put(next);
174	      res.updated.push({ id: next.id, title: next.title, file: skill.file, wasBroken: !!note.broken });
175	      store.log({ op: 'skill', id: next.id, action: 'updated', file: skill.file, wasBroken: !!note.broken });
176	    } else {
177	      const r = createNote(store, card.input, { source });
178	      if (r.error) { res.failed++; res.lastError = new Error(r.error); return; }
179	      res.saved.push({ id: r.note.id, title: r.note.title, file: skill.file });
180	      store.log({ op: 'skill', id: r.note.id, action: 'saved', file: skill.file });
