217	  }
218	  const text = fs.readFileSync(abs, 'utf8');
219	  const changed = verificationChanges(note).filter(c => c.path !== file);
220	  const code = (note.deps || []).filter(d => d.path !== file);
221	  const paths = [...new Set(changed.map(c => c.path))];
222	  const diff = gitDiffFor(repo, note.verifiedCommit, paths);
223	  // a whole file is shown further than a definition: a skill points at a README's section or a script's
224	  // options, which sit past its head (one audit read a section as gone from a README cut at 120 lines)
