238	  const issues = (Array.isArray(v.issues) ? v.issues : []).filter(i => i && String(i.claim || '').trim()).map(i => ({ claim: String(i.claim).trim().slice(0, 400), actual: String(i.actual || '').trim().slice(0, 400), ...(i.pointer ? { pointer: String(i.pointer).slice(0, 200) } : {}) }));
