284	// --- duplicates ----------------------------------------------------------------------------------
285	// Skills that do the same thing: the same name in two roots, or a description and a card whose words
286	// mostly coincide (the card alone is not enough: cards are written to one pattern and two skills of
287	// one area share most of its words).
288	// One is served; the others are archived as its duplicates (restored when the choice changes).
289	// The choice, in order: a person's pin (`skills.prefer` in the config), not broken, more confirmed
290	// than contradicted by sessions, the root the agents look in first (SKILL_ROOTS order), the newer file.
291	export const DUP_JACCARD = 0.6, DUP_DESC_JACCARD = 0.5;
292	const normName = s => String(s || '').toLowerCase().replace(/^\d+[-_.]/, '');
293	function jaccard(a, b) { const A = new Set(a), B = new Set(b); let i = 0; for (const x of A) if (B.has(x)) i++; return i / (A.size + B.size - i || 1); }
294	export function skillClusters(notes) {
295	  const live = notes.filter(n => isSkill(n) && n.status !== 'invalid');
296	  const parent = new Map(live.map(n => [n.id, n.id]));
297	  const find = x => { while (parent.get(x) !== x) x = parent.get(x); return x; };
298	  const union = (a, b) => parent.set(find(a), find(b));
299	  const words = new Map(live.map(n => [n.id, tokenize(`${normName(n.skill?.name).replace(/[-_]/g, ' ')} ${n.applies || ''} ${n.body || ''}`)]));
300	  const desc = new Map(live.map(n => [n.id, tokenize(`${normName(n.skill?.name).replace(/[-_]/g, ' ')} ${n.skill?.description || n.title || ''}`)]));
301	  for (let i = 0; i < live.length; i++) for (let j = i + 1; j < live.length; j++) {
302	    const a = live[i], b = live[j];
303	    if (normName(a.skill?.name) === normName(b.skill?.name) || (jaccard(desc.get(a.id), desc.get(b.id)) >= DUP_DESC_JACCARD && jaccard(words.get(a.id), words.get(b.id)) >= DUP_JACCARD)) union(a.id, b.id);
304	  }
305	  const groups = new Map();
306	  for (const n of live) { const r = find(n.id); if (!groups.has(r)) groups.set(r, []); groups.get(r).push(n); }
307	  return [...groups.values()].filter(g => g.length > 1);
308	}
309	export function preferSkill(group, { prefer = [], repo } = {}) {
310	  const mtime = n => { try { return fs.statSync(repoFile(repo, n.skill.file)).mtimeMs; } catch { return 0; } };
311	  const rootRank = n => { const i = SKILL_ROOTS.indexOf(n.skill?.root); return i < 0 ? SKILL_ROOTS.length : i; };
312	  const net = n => (n.attest?.confirmed || 0) - (n.attest?.contradicted || 0);
313	  return [...group].sort((a, b) => (prefer.includes(b.id) - prefer.includes(a.id)) || ((a.status === 'broken') - (b.status === 'broken')) || (net(b) - net(a)) || (rootRank(a) - rootRank(b)) || (repo ? mtime(b) - mtime(a) : 0) || a.id.localeCompare(b.id))[0];
