289	export async function minePrs(ctx, slug, { from, scan, before, after, again, limit = 20, model, dry, fixes = false, git = false, direct = false, repo = process.cwd(), phase = 'maintenance', directories = null, concurrency = 4, paths = null, pathsLimit = null, pathsScan = null, pathsOnly = false, onProgress = null, distillPrFn = distillPr } = {}) {
290	  const { flags, store, out } = ctx;
291	  // --git: commits from git history although GitHub is reachable (a repository whose work lands by
292	  // direct commits has few pull requests to mine; its fix commits are what review wants)
293	  const useGit = git || !!from || !slug || !hasBin('gh');
294	  if (from) {
295	    try { execFileSync('git', ['rev-parse', '--verify', '--quiet', `${from}^{commit}`], { cwd: repo, stdio: 'ignore' }); }
296	    catch { out(`❌ --from ${from}: not a commit in this repository`); process.exitCode = 1; return { tokens: 0, saved: 0 }; }
297	  }
298	  const recSlug = slug || 'local';
299	  const scopeKey = directories ? projectRecordKey(recSlug, directories) : recSlug;
300	  const rec = minedPrs(store, scopeKey);
301	  if (directories) for (const id of minedPrs(store, recSlug).mined) rec.mined.add(id);
302	  const fetchLimit = Math.min(Math.max(limit * 3, 60), 250);
303	  // --direct: only the commits that name no pull request (the ones PR-only mining never read)
304	  const listFn = direct ? (s, o) => listMergedCommits(repo, { ...o, directories, directOnly: true })
305	    : useGit ? (s, o) => listMergedCommits(repo, { ...o, directories })
306	    : commitsOn(store.config().mining) ? listMergedChanges(repo, { directories }) : listMergedPrs;
307	
308	  // without a window: what was merged since the last run, then further back; never a PR mined before
309	  const fresh = p => again || (!rec.mined.has(p.number) && (!p.hash || !rec.mined.has(p.hash.slice(0, 8))));
310	  // --from scans three times the limit and no further (--scan n: another depth): a recent cache as of
311	  // that commit, not a search for older fixes
312	  // --paths: the history of those files first (--paths-limit of the --limit, half by default), scanned
313	  // three times as deep among the changes touching them (pathsScan: another depth), then the newest
314	  // changes overall fill the rest (pathsOnly: nothing fills it; a focus area's walk, maintain.js)
315	  let targeted = [], history = null;
316	  if (from && paths?.length) {
317	    const want = Math.min(Math.max(1, pathsLimit || Math.ceil(limit / 2)), limit);
318	    const scanLimit = pathsScan || want * 3;
319	    const scanned = listMergedCommits(repo, { from, limit: scanLimit, directories, paths, strict: pathsOnly });
320	    const candidates = mineable(scanned.filter(fresh), { fixes, git: useGit });
321	    targeted = candidates.slice(0, want);
322	    if (pathsOnly) history = { scanned: scanned.length, exhausted: scanned.length < scanLimit && candidates.length <= want };
323	  }
324	  const targetedHashes = new Set(targeted.map(p => p.hash));
325	  const listed = from && pathsOnly ? [] : from ? listMergedCommits(repo, { from, limit: scan || limit * 3, directories }).filter(fresh).filter(p => !targetedHashes.has(p.hash)) : before || after
