327	    : nextPrs(slug, rec, { limit: fetchLimit, list: listFn, repo });
328	  if (!listed.length && !targeted.length) {
329	    const sourceName = useGit ? 'git history' : `merged PRs of ${slug}`;
330	    out(`${history && !history.exhausted ? 'no unmined changes in this history window' : `no ${sourceName} left to mine`} (${rec.mined.size} mined so far)`);
331	    return { tokens: 0, saved: 0, processed: 0, completed: 0, ...history };
332	  }
333	  const failed = new Set();
334	  const scoped = listed.filter(p => !directories || (p.files || []).some(f => includesPath(directories, typeof f === 'string' ? f : f.path || '')));
335	  const candidates = mineable(scoped, { fixes, git: useGit });
336	  if (directories) out(`        ${scoped.length}/${listed.length} scanned changes touch project directories; later runs continue scanning older history.`);
337	  // --from: the newest changes worth distilling at that commit, in order; no ranking chooses among them
338	  const prs = from ? [...targeted, ...candidates.slice(0, Math.max(0, limit - targeted.length))] : pickPrs(candidates, limit);
339	  if (targeted.length) out(`        ${targeted.length} of them touched ${paths.length === 1 ? paths[0] : `${paths.length} given files`}.`);
340	  const deferred = new Set(candidates.filter(p => !prs.includes(p)).map(p => p.number)); // candidates beyond this run's limit wait for the next one
341	  out(`        Reviewing ${prs.length} changes ${useGit ? 'from git history' : `from ${slug}`}. Changes with no reusable notes are normal.`);
342	  const progress = batchProgress({ dir: store.dir, name: 'PR mining', total: prs.length, out, verbose: Boolean(flags.verbose), onProgress });
343	  let tokens = 0, saved = 0;
344	  // a few changes at once: each is one independent model call, and a setup run mines dozens
345	  const queue = [...prs];
346	  const mineOne = async pr => {
347	    const refId = pr.prNumber ? `${recSlug}#${pr.prNumber}` : `${recSlug}#${pr.hash ? pr.hash.slice(0, 8) : pr.number}`;
348	    const item = pr.hash ? `commit ${pr.hash.slice(0, 8)}` : `PR #${pr.number}`;
349	    progress.start(item);
350	    try {
351	      const accounting = { store, phase, pr: pr.number, dry: !!dry };
352	      if (phase !== 'init' && !withinDailyCap(store).ok) throw new Error('daily learning token cap reached; PR will retry');
353	      // the notes already resting on the files the change touched, shown as context rather than evidence
354	      const touched = new Set((pr.files || []).map(f => typeof f === 'string' ? f : f.path)); // git lists paths, GitHub objects
355	      const existing = store.list().filter(n => n.status !== 'invalid' && (n.deps || []).some(d => touched.has(d.path))).slice(0, 12);
356	      const r = await distillPrFn(slug, pr, { model: model || store.config().distillModel || DEFAULT_DISTILL_MODEL, repo, existing, accounting: { ...accounting, purpose: 'mine-prs' } });
357	      tokens += r.tokens || 0;
358	      if (dry) { out(`${oneLine(refId)} ${oneLine(pr.title).slice(0, 60)} → ${r.notes.map(n => n.kind).join(',') || 'no reusable notes'}`); progress.complete({ item, proposed: r.notes }); return; }
359	      const source = { type: 'pr', ref: refId };
360	      // Persist incompleteness before any note can be saved: a process interruption
361	      // must not let legacy note-source inference turn a partial PR into a success.
362	      recordMinedPrs(store, scopeKey, [], { failed: [pr] });
363	      if (directories) recordMinedPrs(store, recSlug, [], { failed: [pr] });
364	      const s2 = saveNotes(store, r.notes, { source, kinds: distillKinds(store) });
365	      saved += s2.saved.length + s2.merged.length;
366	      // mined as soon as its notes are saved, so an interrupted run does not pay for this change again
367	      recordMinedPrs(store, scopeKey, [pr]);
368	      if (directories) recordMinedPrs(store, recSlug, [pr]);
369	      progress.complete({ item, ref: refId, title: pr.title, notes: [...s2.saved, ...s2.merged].map(n => n.id), skipped: s2.skipped.length });
370	    } catch (e) { failed.add(pr.number); progress.complete({ item, ref: refId, title: pr.title, error: e.message }); }
371	  };
372	  await Promise.all(Array.from({ length: Math.max(1, Math.min(concurrency, prs.length)) }, async () => { while (queue.length) await mineOne(queue.shift()); }));
373	  // PRs the filter passed over are recorded too; failed ones and candidates deferred by the limit are not, so the next run takes them again
374	  if (!dry) {
375	    const completed = listed.filter(p => !failed.has(p.number) && !deferred.has(p.number));
376	    recordMinedPrs(store, scopeKey, completed, { failed: prs.filter(p => failed.has(p.number)) });
377	    if (directories) recordMinedPrs(store, recSlug, prs.filter(p => !failed.has(p.number)), { failed: prs.filter(p => failed.has(p.number)) });
378	    store.log({ op: 'mine-prs', slug: recSlug, directories, prs: prs.length - failed.size, passed: listed.length - (prs.length - targeted.length) - deferred.size, deferred: deferred.size, saved, tokens, metered: true, source: useGit ? 'git' : 'github', ...(targeted.length ? { targeted: targeted.length, paths } : {}) });
379	  }
380	  progress.finish({ tokens, retry: 'Failed changes remain unmarked. Retry with: thinker mine-prs' });
381	  return { tokens, saved, failed: failed.size, processed: prs.length, completed: prs.length - failed.size,
382	    ...(history ? { ...history, exhausted: history.exhausted && !failed.size } : {}) };
383	}
