218	  const add = (raw, line) => {
219	    let f = raw.replace(/^\.\//, '');
220	    if (path.isAbsolute(f)) f = path.relative(repo, f);
221	    if (!f || f.startsWith('..')) return;
222	    if (!out.has(f)) {
