196	export function seenFiles(ev, repo, { max = 40 } = {}) {
197	  const text = textOf(ev.tool_response ?? ev.tool_output ?? ev.output).slice(0, 200_000);
198	  const out = new Set();
199	  for (const m of text.matchAll(/(?:^|[\s'"`=:(\[])(\/?(?:[\w.@-]+\/)+[\w.@-]+\.\w{1,5})(?=$|[\s'"`:|;)\],])/gm)) {
