209	// The same sighting, with the lines a search hit: `path:12:` or `path-12-` is a grep hit, a bare path a
210	// listing. Replaying real sessions (research/understanding-variants-2026-10, 2026-10-17), the agent's
211	// first read of a file lands a median of one tool call after the path first appears in a tool result,
212	// and that first appearance is nearly always search output rather than an open — so a sighting is worth
213	// acting on, but `rg --files` or `ls -R` names dozens of files at once. Hits with lines are returned
214	// first and take the budget first, and the lines say where in the file to look (ops.js:onSightOutlines).
215	export function seenHits(ev, repo, { max = 40 } = {}) {
216	  const text = textOf(ev.tool_response ?? ev.tool_output ?? ev.output).slice(0, 200_000);
217	  const out = new Map();
218	  const add = (raw, line) => {
219	    let f = raw.replace(/^\.\//, '');
220	    if (path.isAbsolute(f)) f = path.relative(repo, f);
221	    if (!f || f.startsWith('..')) return;
222	    if (!out.has(f)) {
223	      if (out.size >= max || !fs.existsSync(path.join(repo, f))) return;
224	      out.set(f, []);
225	    }
226	    if (line) out.get(f).push(line);
227	  };
228	  for (const m of text.matchAll(/(?:^|[\s'"`=([])(\/?(?:[\w.@-]+\/)+[\w.@-]+\.\w{1,5}):(\d+)[:-]/gm)) add(m[1], Number(m[2]));
