563	    const copy = path.join(dir, `${backups.size}-config.toml`);
564	    fs.writeFileSync(copy, before, { mode: 0o600 }); backups.set(file, copy);
565	    const root = path.dirname(dir), all = fs.readdirSync(root).sort();
566	    for (const d of all.slice(0, Math.max(0, all.length - BACKUPS_KEPT))) fs.rmSync(path.join(root, d), { recursive: true, force: true });
567	  }
568	  if (before !== changed.text) {
569	    // Refuse to overwrite an edit made while this operation was preparing its backup.
570	    if ((fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '') !== before) throw new Error('Codex config changed concurrently; try again');
571	    writeTheirs(file, changed.text);
572	    if (fs.readFileSync(file, 'utf8') !== changed.text) throw new Error('Codex config was rewritten; try again');
573	    if (!before && !user) excludeFromGit(repo, file);
