575	  return { file, key: 'codex', global, ...(changed.seeded ? { seeded: changed.seeded } : {}), source: { kind: s.kind, name: s.name, id: s.id, dir: s.dir }, prev: changed.prev, created: changed.created, inherited: changed.inherited };
