578	// `thinker harness --undo`: every source the answers switched off here, turned back on.
579	export function undoHarness(store, { home, userHome = os.homedir(), now = Date.now(), names } = {}) {
580	  const st = readHarnessState(store), all = st.applied || [];
581	  const want = names?.length ? new Set(names.map(n => String(n).trim().toLowerCase())) : null;
582	  const applied = want ? all.filter(a => want.has(a.name.toLowerCase()) || want.has(a.key.toLowerCase())) : all, rest = want ? all.filter(a => !applied.includes(a)) : [];
583	  if (!applied.length) return want ? `Nothing switched off here by those names: ${[...want].join(', ')}.` : 'Nothing to undo: thinker has switched nothing off in this repository.';
584	  // each entry on its own: one file that cannot be read keeps its entry for the next try, the rest go back
585	  const backups = new Map(), ctx = { home, now, backups }, back = [], kept = [], app = [];
586	  for (const a of [...applied].reverse()) {
587	    const u = a.undo;
588	    try {
589	      if (u.key === 'codex') { for (const o of u.overrides || []) applyCodex(o.repo, o.source, ctx, o); applyCodex(store.repo, u.source, ctx, u); back.unshift(a.name); continue; }
590	      if (u.key === 'desktop-connector') { app.unshift(a.name); continue; }
591	      if (u.key === 'cursor') { editCursorMcp({ name: u.name, thinkerHome: home || thinkerHome(), home: userHome, write: writeTheirs }, true); back.unshift(a.name); continue; }
592	      editJson(u.file, j => {
593	        if (u.key === 'enabledPlugins') { if (j.enabledPlugins?.[u.id] === false) { if (u.prev === undefined) delete j.enabledPlugins[u.id]; else j.enabledPlugins[u.id] = u.prev; } }
594	        else if (u.key === 'skillOverrides') {
595	          for (const n of u.ids) if (j.skillOverrides?.[n] === 'user-invocable-only') delete j.skillOverrides[n];
596	          if (u.plugin && j.enabledPlugins?.[u.plugin.id] === false) { if (u.plugin.prev === undefined) delete j.enabledPlugins[u.plugin.id]; else j.enabledPlugins[u.plugin.id] = u.plugin.prev; }
597	        }
598	        else if (u.key === 'disabledMcpjsonServers') j.disabledMcpjsonServers = (j.disabledMcpjsonServers || []).filter(n => n !== u.id);
599	        else if (u.key === 'permissions.deny') { if (u.added !== false && j.permissions?.deny) j.permissions.deny = j.permissions.deny.filter(n => n !== u.id); }
600	        else if (u.key === 'disabledMcpServers') { const p = j.projects?.[u.project]; if (p) p.disabledMcpServers = (p.disabledMcpServers || []).filter(n => n !== u.id); }
601	      }, u.key === 'disabledMcpServers' ? { ...ctx, part: j => j.projects?.[u.project] } : ctx);
602	      back.unshift(a.name);
603	    } catch (e) { kept.push({ ...a, undoError: e.message }); }
604	  }
605	  if (kept.length || rest.length) st.applied = [...rest, ...kept]; else delete st.applied;
606	  delete st.recalled; saveState(store, st);
607	  store.log({ op: 'harness-undo', sources: back.length + app.length, failed: kept.length });
608	  return [back.length ? `Turned back on, from the next session on: ${back.join(', ')}.` : '',
609	    app.length ? `Turn ${app.join(', ')} back on in the Claude desktop app: the + menu → Connectors (or ask Claude there); thinker no longer counts ${app.length === 1 ? 'it' : 'them'} as off.` : '',
610	    kept.length ? `Not turned back on: ${kept.map(k => `${k.name} (${k.undoError})`).join('; ')}; \`thinker harness --undo\` tries again.` : ''].filter(Boolean).join(' ');
611	}
