89	    if (!Array.isArray(m?.content)) continue;
90	    if (m.role === 'user') for (const b of m.content) if (b?.type === 'tool_result') results.push(textLen(b.content));
91	    if (m.role === 'assistant') for (const b of m.content) if (b?.type === 'tool_use') inputs.push(JSON.stringify(b.input ?? {}).length);
92	  }
93	  const sum = a => a.slice(0, Math.max(0, a.length - keep)).reduce((x, y) => x + y, 0);
