103	// what sits before the turn: within a turn the request grows with every call, and a verdict that moved from one
104	// call of a turn to the next would move the edit with it, which is the rewrite this exists to avoid.
105	export function measureClearing(cfg, j, clearedUses = 0) {
106	  const txt = v => { try { return v == null ? 0 : JSON.stringify(v).length; } catch { return 0; } };
107	  const tok = chars => Math.floor(chars * TOKENS_PER_CHAR);
108	  const all = Array.isArray(j?.messages) ? j.messages : [];
109	  const messages = all.slice(0, turnStart(all));
110	  const head = txt(j?.system) + txt(j?.tools);
111	  const prompt = tok(head + txt(messages));
112	  const keep = keepForTurn(cfg, all);
113	  return { prompt, prefix: Math.min(prompt, tok(head)), before: clearableBeforeTurn(cfg, all, keep), turn: turnId(all), keep };
