115	// the boundary's id: how many prompts of the person's the conversation holds, by turnStart's rule for one
116	export function turnId(messages) {
117	  let n = 0;
118	  for (const m of Array.isArray(messages) ? messages : []) {
119	    if (m?.role !== 'user') continue;
120	    const blocks = Array.isArray(m.content) ? m.content : [{ type: 'text' }];
121	    if (blocks.some(b => b?.type === 'text') && !blocks.some(b => b?.type === 'tool_result')) n++;
