516	    // a 1h write is ~2x an input token, a 5m write ~1.25x, against a cache read at ~2.5% of one. So the same clear
517	    // is worth 80 avoided reads at 1h and 50 at 5m, and the decision (clearing.js:price) cannot judge a clear without knowing which.
518	    if (u?.cache_creation) {
519	      if (u.cache_creation.ephemeral_1h_input_tokens != null) seen.write1h = u.cache_creation.ephemeral_1h_input_tokens;
520	      if (u.cache_creation.ephemeral_5m_input_tokens != null) seen.write5m = u.cache_creation.ephemeral_5m_input_tokens;
521	    }
